INSERT INTO knowledge_chunks VALUES(4,1,1,'Pentingnya Pertolongan Pertama','Halaman 4',4,unistr('Seorang Penolong Pertama mempunyai KEWAJIBAN sebagai\u000aberikut:\u000aè\u000aMenjaga keselamatan diri, anggota tim, penderita dan orang di\u000asekitarnya\u000aè\u000aMenjangkau penderita\u000aè\u000aMengenali dan mengatasi masalah yang mengancam nyawa\u000aè\u000aMeminta bantuan / rujukan\u000aè\u000aMemberikan pertolongan dengan cepat dan tepat sesuai keadaan\u000apenderita\u000aè\u000aMembantu penolong yang lain\u000aè\u000aMenjaga kerahasiaan medis penderita\u000aè\u000aMelakukan komunikasi dengan petugas lain yang terlibat\u000aè\u000aMempersiapkan penderita untuk ditransportasi / dirujuk ke fasilitas\u000akesehatan\u000aKualifikasi Penolong Pertama :\u000aè\u000aJujur dan bertanggungjawab\u000aè\u000aProfesional\u000aè\u000aMempunyai kematangan emosi\u000aè\u000aMampu bersosialisasi\u000aè\u000aKemampuan nyata terukur sesuai sertifikasi\u000aè\u000aMempunyai kondisi fisik baik\u000aè\u000aMempunyai rasa bangga\u000a4'),'{"seorang":0.0136986301369863,"penolong":0.0410958904109589,"pertama":0.0273972602739726,"mempunyai":0.0547945205479452,"kewajiban":0.0136986301369863,"sebagai":0.0136986301369863,"berikut":0.0136986301369863,"menjaga":0.0273972602739726,"keselamatan":0.0136986301369863,"diri":0.0136986301369863,"anggota":0.0136986301369863,"tim":0.0136986301369863,"penderita":0.0684931506849315,"orang":0.0136986301369863,"sekitarnya":0.0136986301369863,"menjangkau":0.0136986301369863,"mengenali":0.0136986301369863,"mengatasi":0.0136986301369863,"masalah":0.0136986301369863,"mengancam":0.0136986301369863,"nyawa":0.0136986301369863,"meminta":0.0136986301369863,"bantuan":0.0136986301369863,"rujukan":0.0136986301369863,"memberikan":0.0136986301369863,"pertolongan":0.0136986301369863,"cepat":0.0136986301369863,"tepat":0.0136986301369863,"sesuai":0.0273972602739726,"keadaan":0.0136986301369863,"membantu":0.0136986301369863,"lain":0.0273972602739726,"kerahasiaan":0.0136