INSERT INTO knowledge_chunks VALUES(6,1,2,'Alat Perlindungan Diri (APD)','Halaman 6',6,unistr('Alat Perlindungan Diri (APD)\u000aYang Perlu Disiapkan\u000aS\u000aebagai pelaku PP, kita juga harus mengutamakan keselamatan diri\u000asendiri. Jadi, kita memerlukan Alat Perlindungan Diri (APD).\u000aAPD itu adalah alat yang digunakan agar kita tidak tertular penyakit. Alat\u000aperlindungan diri tidak perlu mahal.\u000aContohnya :\u000a- Sarung tangan lateks\u000a- Masker penolong\u000a- Kacamata pelindung\u000aKamu Harus Tau!\u000aDarah dan semua cairan tubuh bisa menularkan penyakit...!\u000aSelain APD, dalam melakukan PP kita juga memerlukan beberapa peralatan.\u000aMisalnya :\u000a- Kasa Steril\u000a- Pembalut gulung / perban\u000a- Pembalut perekat / plester\u000a- Gunting pembalut\u000a- Bidai\u000a- Alkohol 70%\u000a- Pinset\u000a- Kapas\u000a- Senter\u000a- Selimut\u000a6'),'{"alat":0.05405405405405406,"perlindungan":0.04054054054054054,"diri":0.05405405405405406,"apd":0.05405405405405406,"perlu":0.02702702702702703,"disiapkan":0.013513513513513514,"ebagai":0.013513513513513514,"pelaku":0.013513513513513514,"kita":0.05405405405405406,"mengutamakan":0.013513513513513514,"keselamatan":0.013513513513513514,"sendiri":0.013513513513513514,"jadi":0.013513513513513514,"memerlukan":0.02702702702702703,"digunakan":0.013513513513513514,"agar":0.013513513513513514,"tidak":0.02702702702702703,"tertular":0.013513513513513514,"penyakit":0.02702702702702703,"mahal":0.013513513513513514,"contohnya":0.013513513513513514,"sarung":0.013513513513513514,"tangan":0.013513513513513514,"lateks":0.013513513513513514,"masker":0.013513513513513514,"penolong":0.013513513513513514,"kacamata":0.013513513513513514,"pelindung":0.013513513513513514,"kamu":0.013513513513513514,"tau":0.013513513513513514,"darah":0.013513513513513514,"semua":0.013513513513513514,"cairan":0.013513513513513514,"tubuh":0.013513513513513514,"menularkan":0.013513513513513514,"selain":0.013513513513513514,"melakukan":0.