INSERT INTO knowledge_chunks VALUES(8,1,3,'Mengenali Anatomi dan Faal Dasar','Halaman 8',8,unistr('D\u000aalam melakukan Pertolongan Pertama (PP), Kita juga harus tahu apa itu\u000aAnatomi dan Faal Dasar.\u000aAnatomi adalah ilmu urai tubuh. Yaitu ilmu yang mempelajari susunan\u000adan bentuk tubuh. Sedangkan ilmu faal yaitu ilmu yang mempelajari\u000afungsi bagian dari alat atau jaringan tubuh disebut Fisiologi.\u000aPOSISI ANATOMIS\u000aAdalah posisi dimana tubuh kita\u000aberdiri tegak, kedua lengan di\u000asamping tubuh, telapak tangan\u000amenghadap ke depan.\u000aBerdasarkan posisi anatomis ini\u000adikenal ada tiga bidang khayal yang\u000amembagi tubuh menjadi dua\u000abagian, yaitu:\u000a1. Bidang Medial\u000aBidang khayal yang membagi\u000atubuh menjadi dua, yaitu kiri\u000adan kanan\u000a2. Bidang Frontal\u000aBidang khayal yang membagi\u000atubuh menjadi depan\u000a(anterior) dan belakang\u000a(posterior)\u000a3. Bidang Transversal\u000aBidang khayal yang membagi\u000atubuh menjadi dua, yaitu atas\u000a(superior) dan bawah\u000a(inferior).\u000a8'),'{"alam":0.010638297872340425,"melakukan":0.010638297872340425,"pertolongan":0.010638297872340425,"pertama":0.010638297872340425,"kita":0.02127659574468085,"tahu":0.010638297872340425,"apa":0.010638297872340425,"anatomi":0.02127659574468085,"faal":0.02127659574468085,"dasar":0.010638297872340425,"ilmu":0.0425531914893617,"urai":0.010638297872340425,"tubuh":0.09574468085106383,"yaitu":0.05319148936170213,"mempelajari":0.02127659574468085,"susunan":0.010638297872340425,"bentuk":0.010638297872340425,"sedangkan":0.010638297872340425,"fungsi":0.010638297872340425,"bagian":0.02127659574468085,"alat":0.010638297872340425,"jaringan":0.010638297872340425,"disebut":0.010638297872340425,"fisiologi":0.010638297872340425,"posisi":0.031914893617021274,"anatomis":0.02127659574468085,"dimana":0.010638297872340425,"berdiri":0.010638297872340425,"tegak":0.010638297872340425,"kedua":0.010638297872340425,"lengan":0.010638297872340