INSERT INTO knowledge_chunks VALUES(9,1,3,'Mengenali Anatomi dan Faal Dasar','Halaman 9',9,unistr('BAGIAN-BAGIAN TUBUH MANUSIA\u000aTubuh manusia dilindungi oleh kulit dan diperkuat oleh rangka.\u000aUmumnya tubuh manusia dibagi menjadi 5 bagian, yaitu :\u000a1. Kepala\u000aTerdiri dari :\u000aTengkorak, wajah dan rahang bawah\u000a2. Leher\u000a3. Batang Tubuh\u000aTerdiri dari :\u000aDada, perut, punggung dan panggul\u000a4. Anggota Gerak Atas\u000aTerdiri dari :\u000a?\u000aSendi bahu\u000a?\u000aLengan atas\u000a?\u000aSiku\u000a?\u000aLengan bawah\u000a?\u000aPergelangan tangan\u000a?\u000aTangan\u000a5. Anggota Gerak Bawah\u000aTerdiri dari :\u000a?\u000aSendi panggul\u000a?\u000aTungkai atas (paha)\u000a?\u000aLutut\u000a?\u000aTungkai bawah\u000a?\u000aPergelangan kaki\u000a?\u000aKaki\u000a9'),'{"bagian-bagian":0.01694915254237288,"tubuh":0.06779661016949153,"manusia":0.05084745762711865,"dilindungi":0.01694915254237288,"kulit":0.01694915254237288,"diperkuat":0.01694915254237288,"rangka":0.01694915254237288,"umumnya":0.01694915254237288,"dibagi":0.01694915254237288,"menjadi":0.01694915254237288,"bagian":0.01694915254237288,"yaitu":0.01694915254237288,"kepala":0.01694915254237288,"terdiri":0.06779661016949153,"tengkorak":0.01694915254237288,"wajah":0.01694915254237288,"rahang":0.01694915254237288,"bawah":0.06779661016949153,"leher":0.01694915254237288,"batang":0.01694915254237288,"dada":0.01694915254237288,"perut":0.01694915254237288,"punggung":0.01694915254237288,"panggul":0.03389830508474576,"anggota":0.03389830508474576,"gerak":0.03389830508474576,"atas":0.05084745762711865,"sendi":0.03389830508474576,"bahu":0.01694915254237288,"lengan":0.03389830508474576,"siku":0.01694915254237288,"pergelangan":0.03389830508474576,"tangan":0.03389830508474576,"tungkai":0.03389830508474576,"paha":0.01694915254237288,"lutut":0.01694915254237288,"kaki":0.03389830508474576}','ACTIVE','2026-09-13 11:56:41','2026-09-13 11:56:41');
INSERT INTO knowledge_chunks VALUES(10,1,3,'Mengenali Anatomi dan Faal Dasar','Halaman 10',10,unistr('TENTANG RONGGA\u000aSelain pembagian tubuh, ternyata tubuh kita terdapat 5 (lima) buah rongga,\u000ayaitu :\u000a1. Rongga Tengkorak\u000aRongga ini berisi otak dan melindunginya.\u000a2. Rongga Tulang Belakang\u000aBerisi bumbung syaraf atau “spinal cord”\u000aterbentuk dari rongga-rongga tulang\u000abelakang menyatu membentuk suatu\u000akolom.\u000a3. Rongga Dada\u000aSering juga disebut rongga toraks.\u000aDilindungi oleh tulang-tulang rusuk,\u000aberisi jantung, paru-paru, pembuluh\u000adarah besar, kerongkongan dan saluran\u000apernapasan.\u000a4. Rongga Perut\u000aRongga ini terletak diantara rongga dada\u000adan rongga panggul. Dalam dunia medis\u000adikenal dengan istilah abdomen. Di dalam\u000arongga ini terdapat berbagai organ\u000apencernaan dan kelenjar seperti\u000alambung, usus, limpa, hati, empedu,\u000apancreas dan lainnya.\u000a5. Rongga Panggul\u000aRongga ini dibentuk oleh tulang – tulang\u000apanggul, berisi kandung kemih, sebagian\u000ausus besar dan organ reproduksi dalam.\u000a10'),'{"tentang":0.010526315789473684,"rongga":0.14736842105263157,"selain":0.010526315789473684,"pembagian":0.010526315789473684,"tubuh":0.021052631578947368,"ternyata":0.010526315789473684,"kita":0.010526315789473684,"terdapat":0.021052631578947368,"lima":0.010526315789473684,"buah":0.010526315789473684,"yaitu":0.010526315789473684,"tengkorak":0.010526315789473684,"berisi":0.042105263157894736,"otak":0.010526315789473684,"melindunginya":0.010526315789473684,"tulang":0.042105263157894736,"belakang":0.021052631578947368,"bumbung":0.010526315789473684,"syaraf":0.010526315789473684,"spinal":0.010526315789473684,"cord":0.010526315789473684,"terbentuk":0.010526315789473684,"rongga-rongga":0.010526315789473684,"menyatu":0.010526315789473684,"membentuk":0.010526315789473684,"suatu":0.010526315789473684,"kolom":0.010526315789473684,"dada":0.021052631578947368,"sering":0.0105263