INSERT INTO knowledge_chunks VALUES(12,1,3,'Mengenali Anatomi dan Faal Dasar','Halaman 12',12,unistr('7.\u000aSistem Kelenjar Buntu (Endokrin)\u000aKelenjar yang mengirimkan hasil sekresinya ( produknya ) kedalam darah\u000adalam jaringan kelenjar tampa melalui saluran dan hasil sekresi ini\u000adisebut hormon.\u000a8.\u000aSistem Kemih (Urinaria)\u000aProses penyaringan darah untuk menyerap zat yang digunakan tubuh yang\u000amembebaskan dari zat yang tidak digunakan.\u000a9.\u000aKulit\u000aAdalah lapisan jaringan pada bagian luar yang menutupi dan melindungi\u000apermukaan tubuh dan yang berhubungan dengan selaput lendir yang\u000amelapisi rongga-rongga, lubang masuk.\u000a10. Panca Indera\u000aPancaindera adalah organ untuk menerima jenis rangsangan atau\u000astimulus tertentu. Terdiri dari :\u000a?\u000aIndera Penglihatan (Mata)\u000a?\u000aIndera Pendengaran (Telinga)\u000a?\u000aIndera Penciuman (Hidung)\u000a?\u000aIndera Pengecap (Lidah)\u000a?\u000aIndera Perasa/Peraba (Kulit)\u000a11. Sistem Reproduksi\u000aTerdiri dari Sistem reproduksi Pria dan Sistem reproduksi Wanita.\u000a12'),'{"sistem":0.058823529411764705,"kelenjar":0.03529411764705882,"buntu":0.011764705882352941,"endokrin":0.011764705882352941,"mengirimkan":0.011764705882352941,"hasil":0.023529411764705882,"sekresinya":0.011764705882352941,"produknya":0.011764705882352941,"kedalam":0.011764705882352941,"darah":0.023529411764705882,"jaringan":0.023529411764705882,"tampa":0.011764705882352941,"melalui":0.011764705882352941,"saluran":0.011764705882352941,"sekresi":0.011764705882352941,"disebut":0.011764705882352941,"hormon":0.011764705882352941,"kemih":0.011764705882352941,"urinaria":0.011764705882352941,"proses":0.011764705882352941,"penyaringan":0.011764705882352941,"menyerap":0.011764705882352941,"zat":0.023529411764705882,"digunakan":0.023529411764705882,"tubuh":0.023529411764705882,"membebaskan":0.011764705882352941,"tidak":0.011764705882352941,"kulit":0.023529411764705882,"lapisan":0.011764705