INSERT INTO knowledge_chunks VALUES(16,1,4,'Penilaian Korban','Halaman 16',16,unistr('e. Menilai denyut nadi\u000aSebelum melakukannya, kita lihat dulu kondisi korban apakah sadar atau\u000atidak. Jika sadar, cara yang digunakan adalah dengan meraba nadi\u000apergelangan tangan (radial). Sedangkan bagi korban yang tidak sadar,\u000anadi yang diperiksa adalah di bagian leher (Carotis)\u000aKorban Sadar\u000aKorban Tidak Sadar\u000af. Hubungi Bantuan\u000aUsahakan untuk segera minta bantuan rujukan. Kita bisa meminta\u000abantuan kepada orang lain atau melakukannya sendiri. Misalnya dengan\u000atelepon.\u000aJANGAN LUPA!!!\u000aCatat Nomor Telepon Penting Darurat di tempatmu...\u000a16'),'{"menilai":0.01639344262295082,"denyut":0.01639344262295082,"nadi":0.04918032786885246,"sebelum":0.01639344262295082,"melakukannya":0.03278688524590164,"kita":0.03278688524590164,"lihat":0.01639344262295082,"dulu":0.01639344262295082,"kondisi":0.01639344262295082,"korban":0.06557377049180328,"apakah":0.01639344262295082,"sadar":0.08196721311475409,"tidak":0.04918032786885246,"cara":0.01639344262295082,"digunakan":0.01639344262295082,"meraba":0.01639344262295082,"pergelangan":0.01639344262295082,"tangan":0.01639344262295082,"radial":0.01639344262295082,"sedangkan":0.01639344262295082,"bagi":0.01639344262295082,"diperiksa":0.01639344262295082,"bagian":0.01639344262295082,"leher":0.01639344262295082,"carotis":0.01639344262295082,"hubungi":0.01639344262295082,"bantuan":0.04918032786885246,"usahakan":0.01639344262295082,"segera":0.01639344262295082,"minta":0.01639344262295082,"rujukan":0.01639344262295082,"meminta":0.01639344262295082,"kepada":0.01639344262295082,"orang":0.01639344262295082,"lain":0.01639344262295082,"sendiri":0.01639344262295082,"misalnya":0.01639344262295082,"telepon":0.03278688524590164,"jangan":0.01639344262295082,"lupa":0.01639344262295082,"catat":0.01639344262295082,"nomor":0.01639344262295082,"penting":0.01639344262295082,"darurat":0.01639344262295082,"tempatmu":0.