INSERT INTO knowledge_chunks VALUES(17,1,4,'Penilaian Korban','Halaman 17',17,unistr('3. Pemeriksaan Fisik\u000aTindakan ini melibatkan penglihatan, perabaan dan pendengaran.\u000aTanda apa saja yang perlu kita temukan saat melakukan pemeriksaan\u000afisik???\u000a1. Apakah ada Perubahan bentuk pada bagian tubuh si korban?\u000a2. Apakah ada Luka terbuka (terlihat jelas) pada tubuh korban?\u000a3. Apakah korban merasakan Nyeri saat bagian tubuhnya kita raba\u000aatau tekan?\u000a4. Apakah ada Bengkak pada tubuh korban?\u000aAgar lebih mudah mengingatnya, kita menyebut tanda-tanda\u000atersebut dengan isilah PLNB.\u000aUntuk pemeriksaan lebih lanjut kondisi korban,\u000aperlu dilakukan pemeriksaan yang lebih lengkap\u000adari ujung kepala sampai ujung kaki.\u000a1. Kepala\u000aÊ\u000aTelinga\u000aÊ\u000aHidung\u000aÊ\u000aMata\u000aÊ\u000aMulut\u000a2. Leher\u000a3. Dada\u000a4. Perut\u000a5. Punggung\u000a6. Panggul\u000a7. Anggota gerak atas\u000adan bawah.\u000aPENTING!\u000aPada pemeriksaan anggota\u000agerak selain PLNB juga\u000alakukan pemeriksaan gerakan\u000asensasi dan sirkulasi.\u000a17'),'{"pemeriksaan":0.06521739130434782,"fisik":0.021739130434782608,"tindakan":0.010869565217391304,"melibatkan":0.010869565217391304,"penglihatan":0.010869565217391304,"perabaan":0.010869565217391304,"pendengaran":0.010869565217391304,"tanda":0.010869565217391304,"apa":0.010869565217391304,"saja":0.010869565217391304,"perlu":0.021739130434782608,"kita":0.03260869565217391,"temukan":0.010869565217391304,"melakukan":0.010869565217391304,"apakah":0.043478260869565216,"perubahan":0.010869565217391304,"bentuk":0.010869565217391304,"bagian":0.021739130434782608,"tubuh":0.03260869565217391,"korban":0.05434782608695652,"luka":0.010869565217391304,"terbuka":0.010869565217391304,"terlihat":0.010869565217391304,"jelas":0.010869565217391304,"merasakan":0.010869565217391304,"nyeri":0.010869565217391304,"tubuhnya":0.010869565217391304,"raba":0.010869565217391304,"tekan":0.010869565217391