INSERT INTO knowledge_chunks VALUES(20,1,4,'Penilaian Korban','Halaman 20',20,unistr('RIWAYAT PENDERITA\u000aUntuk mengetahui penyebab atau pencetus suatu kejadian, mekanisme\u000akejadian atau perjalanan suatu penyakit maka diperlukan wawancara yang\u000adapat dilakukan dengan penderita, keluarganya atau saksi mata. Riwat\u000apenderita ini sangat penting pada kasus medis.Untuk memudahkan, dikenal\u000aakronim KOMPAK .\u000aK = Keluhan utama\u000aSesuatu yang sangat dikeluhkan penderita . Gejala adalah hal-hal yang\u000ahanya dapat dirasakan oleh penderita misalnya nyeri, pusing. Tanda\u000aadalah hal-hal yang dapat diamati oleh orang lain . Saat melakukan Tanya\u000ajawab hindari jawaban YA atau TIDAK. Usahakan memberikan pertanyaan\u000aterbuka .\u000aO = Obat – obatan yang diminum\u000aTanyakan apakah penderita sedang dalam proses pengobatan. Gangguan\u000ayang dialami mungkin akibat lupa minum atau menelan obat tertentu\u000acontohnya seorang penderita kencing manis mengalami masalah kadar\u000agula derah yang tinggi karena lupa minum obat sebelum makan.\u000aM = Makanan / Minuman terakhir\u000aHal ini dapat dijadikan dasar terjadinya kehilangan kesadaran pada\u000apenderita. Selain itu data ini juga penting untuk diketahui bila ternyata\u000apenderita harus menjalai pembedahan di RS.\u000aP = Penyakit yang diderita\u000aRiwayat penyakit yang sedang diderita atau pernah diderita yang\u000amungkin berhubungan dengan keadaan yang dialami penderita saat ini.\u000aContoh : asma dan jantung.\u000aA = Alergi yang Dialami\u000aPerlu dicari apakah penyebab pada penderita ini mungkin merupakan\u000asuatu bentuk alergi terhadap bahan-bahan tertentu . umumnya penderita\u000aatau keluarga sudah mengetahuinya dan sudah memahami mengatasi\u000akeadaan itu.\u000aK = Kejadian\u000aKejadian yang dialami penderita sebelum kecelakaan atau sebelum\u000atimbulnya Waspadai Gejala dan Tandanya! penyakit yang diderita saat ini.\u000aINGAT!!!\u000aPenolong tidak membuat diagnosa, tetapi dapat membuat\u000akesimpulan berdasarkan hasil temuannya.\u000a20'),'{"riwayat":0.0111731843575419,"penderita":0.07262569832402235,"mengetahui":0.00558659217877095,"penyebab":0.0111731843575419,"pencetus":0.00558659217877095,"suatu":0.01675977653631285,"kejadian":0.0223463687150838,"mekanisme":0.00558659217877095,"perjalanan":0.00558659217877095,"penyakit":0.0223463687150838,"maka":0.00558659217877095,"diperlukan":0.00558659217877095,"wawancara":0.00558659217877095,"dapat":0.027932960893854747,"dilakukan":0.00558659217877095,"keluarganya":0.00558659217877095,"saksi":0.00558659217877095,"mata":0.00558659217877095,"riwat":0.00558659217877095,"sangat":0.0111731843575419,"penting":0.0111731843575419,"kasus":0.00558659217877095,"medis":0.00558659217877095,"memudahkan":0.00558659217877095,"dikenal":0.00558659217877095,"akronim":0.00558659217877095,"kompak":0.00558659217877095,"keluhan":0.00558659217877095,"utama":0.00558659217877095,"sesuatu":0.00558659217877095,"dikeluhkan":0.00558659217877095,"gejala":0.0111731843575419,"hal-hal":0.0111731843575419,"hanya":0.00558659217877095,"dirasakan":0.00558659217877095,"misalnya":0.00558659217877095,"nyeri":0.00558659217877095,"pusing":0.00558659217877095,"tanda":0.00558659217877095,"diamati":0.00558659217877095,"orang":0.00558659217877095,"lain":0.00558659217877095,"melakukan":0.00558659217877095,"tanya":0.00558659217877095,"jawab":0.00558659217877095,"hindari":0.00558659217877095,"jawaban":0.00558659217877095,"tidak":0.0111731843575419,"usahakan":0.00558659217877095,"memberikan":0.00558659217877095,"pertanyaan":0.00558659217877095,"terbuka":0.00558659217877095,"obat":0.01675977653631285,"obatan":0.00558659217877095,"diminum":0.00558659217877095,"tanyakan":0.00558659217877095,"apakah":0.0111731843575419,"sedang":0.0111731843575419,"proses":0.00558659217877095,"pengobatan":0.00558659217877095,"gangguan":0.00558659217877095,"dialami":0.0223463687150838,"mungkin":0.01675977653631285,"akibat":0.00558659217877095,"lupa":0.0111731843