INSERT INTO knowledge_chunks VALUES(21,1,4,'Penilaian Korban','Halaman 21',21,unistr('PEMERIKSAAN BERKALA\u000aUsahakan pemeriksaan terus dilanjutkan secara berkelanjutan sebelum\u000amendapat pertolongan medis. Secara umum pada pemeriksaan berkala harus\u000adinilai kembali :\u000a- Tingkat kesadaran\u000a- Nilai kembali jalan napas dan perbaii bila perlu\u000a- Nilai kembali pernapasan, frekuensi dan kualitasnya\u000a- Periksa kembali nadi penderita\u000a- Nilai kembali keadaan kulit : Suhu, kelembaban dan kondisinya\u000a- Periksa kembali secara seksama mungkin ada bagian yang belum\u000adiperiksa atau sengaja di lewati\u000a- Nilai kembali penatalaksanaan penderita (secara keseluruhan)\u000a- Pertahankan komunikasi dengan penderita untuk menjaga rasa aman dan\u000anyaman.\u000aPELAPORAN\u000aSetelah selesai menangani penderita dan penolong melakukannya dalam tugas\u000amaka semua pemeriksaan dan tindakan pertolongan harus dilaporkan secara\u000asingkat dan jelas kepada penolong selanjutnya.\u000aDalam laporan sebaiknya dicantumkan :\u000a- Umur dan jenis kelamin penderita\u000a- Keluhan utama\u000a- Tingkat kesadaran\u000a- Keadaan jalan napas\u000a- Pernapasan\u000a- Denyut nadi\u000a- Pemeriksaan yang penting\u000a- KOMPAK yang penting\u000a- Penatalaksanaan\u000a- Perkembangan lainnya yang dianggap penting\u000a21'),'{"pemeriksaan":0.047619047619047616,"berkala":0.01904761904761905,"usahakan":0.009523809523809525,"terus":0.009523809523809525,"dilanjutkan":0.009523809523809525,"secara":0.047619047619047616,"berkelanjutan":0.009523809523809525,"sebelum":0.009523809523809525,"mendapat":0.009523809523809525,"pertolongan":0.01904761904761905,"medis":0.009523809523809525,"umum":0.009523809523809525,"dinilai":0.009523809523809525,"tingkat":0.01904761904761905,"kesadaran":0.01904761904761905,"nilai":0.0380952380952381,"jalan":0.01904761904761905,"napas":0.01904761904761905,"perbaii":0.009523809523809525,"bila":0.009523809523809525,"perlu":0.009523809523809525,"pernap