INSERT INTO knowledge_chunks VALUES(31,1,6,'Cedera Sistem Otot Rangka','Halaman 31',31,unistr('4.Terkilir Sendi (Sprain)\u000aTerkilir Sendi adalah robek atau putusnya jaringan ikat sekitar sendi karena\u000asendi teregang melebihi batas normal .\u000aPenyebab :\u000aTerpeleset, gerakan yang salah .\u000aWaspadai Gejala dan Tandanya!\u000a- Bengkak\u000a- Nyeri Gerak\u000a- Nyeri Tekan\u000a- Warna kulit merah kebiruan\u000aPertolongan cedera pada sistem otot rangka:\u000a-\u000aLakukan penilaian dini.\u000aLakukan pemeriksaan Fisik\u000aStabilkan bagian yang patah secara manual\u000aUpayakan yang diduga patah dapat dilihat\u000aAtasi perdarahan dan rawat luka bila ada\u000aSiapkan alat-alat seperlunya ( bidai dan mitella )\u000aLAKUKAN PEMBIDAIAN……!!!\u000aKurangi rasa sakit\u000aBaringkan penderita pada posisi yang nyaman.\u000aPenanganan Terkilir :\u000a- Letakkan penderita dalam\u000aposisi yang nyaman,\u000aistirahatkan bagian yang\u000acedera\u000a- Tinggikan bagian yang\u000acedera\u000a- Beri kompres dingin\u000amaksimum 3 menit, ulangi\u000asetiap jam bila perlu\u000a- Balut tekan dan tetap\u000atinggikan\u000a- Rawat sebagai patah tulang\u000a- Rujuk ke fasilitas kesehatan\u000a31'),'{"terkilir":0.02857142857142857,"sendi":0.0380952380952381,"sprain":0.009523809523809525,"robek":0.009523809523809525,"putusnya":0.009523809523809525,"jaringan":0.009523809523809525,"ikat":0.009523809523809525,"sekitar":0.009523809523809525,"teregang":0.009523809523809525,"melebihi":0.009523809523809525,"batas":0.009523809523809525,"normal":0.009523809523809525,"penyebab":0.009523809523809525,"terpeleset":0.009523809523809525,"gerakan":0.009523809523809525,"salah":0.009523809523809525,"waspadai":0.009523809523809525,"gejala":0.009523809523809525,"tandanya":0.009523809523809525,"bengkak":0.009523809523809525,"nyeri":0.01904761904761905,"gerak":0.009523809523809525,"tekan":0.01904761904761905,"warna":0.009523809523809525,"kulit":0.009523809523809525,"merah":0.009523809523809525,