INSERT INTO knowledge_chunks VALUES(35,1,7,'Luka Bakar','Halaman 35',35,unistr('Luas permukaan luka bakar\u000aDalam penangan luka bakar dan penentuan derajat berat luka bakar, luas\u000apermukaan tubuh yang mengalami luka bakar sangat berperan. Pedoman\u000auntuk memperkirakan luas daerah yang terbakar dilakukan dengan Hukum 9\u000a(rule of nine) yaitu dengan membagi daerah tub\u000a4,5%\u000a4,5%\u000a4,5%\u000a18%\u000a4,5%\u000a4,5%\u000a18%\u000a4,5%\u000aHukum 9 pada orang anak-anak\u000a1%\u000a9%\u000a9%\u000a9%\u000a9%\u000a9%\u000a9%\u000a18%\u000a18%\u000a4,5%\u000a4,5%\u000a4,5%\u000a4,5%\u000aHukum 9 pada orang dewasa\u000a7%\u000a7%\u000a7%\u000a7%\u000a35'),'{"luas":0.07692307692307693,"permukaan":0.05128205128205128,"luka":0.10256410256410256,"bakar":0.10256410256410256,"penangan":0.02564102564102564,"penentuan":0.02564102564102564,"derajat":0.02564102564102564,"berat":0.02564102564102564,"tubuh":0.02564102564102564,"mengalami":0.02564102564102564,"sangat":0.02564102564102564,"berperan":0.02564102564102564,"pedoman":0.02564102564102564,"memperkirakan":0.02564102564102564,"daerah":0.05128205128205128,"terbakar":0.02564102564102564,"dilakukan":0.02564102564102564,"hukum":0.07692307692307693,"rule":0.02564102564102564,"nine":0.02564102564102564,"yaitu":0.02564102564102564,"membagi":0.02564102564102564,"tub":0.02564102564102564,"orang":0.05128205128205128,"anak-anak":0.02564102564102564,"dewasa":0.02564102564102564}','ACTIVE','2026-09-13 11:56:47','2026-09-13 11:56:47');
INSERT INTO knowledge_chunks VALUES(36,1,7,'Luka Bakar','Halaman 36',36,unistr('Penangangan Luka Bakar :\u000a1. Alirkan air biasa ke daerah yang luka, bila ada bahan kimia alirkan air\u000aterus menerus selama 20 menit atau lebih\u000a2. Lepaskan pakaian dan perhiasan, jika pakaian melekat pada luka bakar\u000agunting sekitarnya jangan memaksa untuk melepasnya\u000a3. Tutup luka bakar, gunakan penutup luka steril (kassa Steril), jangan\u000amemecahkan gelembung.\u000a4. Jangan gunakan mentega, odol, oli, kecap, kopi, air es.\u000a5. Rujuk ke fasilitas kesehatan\u000aES\u000a36'),'{"penangangan":0.018867924528301886,"luka":0.09433962264150944,"bakar":0.05660377358490566,"alirkan":0.03773584905660377,"air":0.05660377358490566,"biasa":0.018867924528301886,"daerah":0.018867924528301886,"bila":0.018867924528301886,"bahan":0.018867924528301886,"kimia":0.018867924528301886,"terus":0.018867924528301886,"menerus":0.018867924528301886,"selama":0.018867924528301886,"menit":0.018867924528301886,"lebih":0.018867924528301886,"lepaskan":0.018867924528301886,"pakaian":0.03773584905660377,"perhiasan":0.018867924528301886,"melekat":0.018867924528301886,"gunting":0.018867924528301886,"sekitarnya":0.018867924528301886,"jangan":0.05660377358490566,"memaksa":0.018867924528301886,"melepasnya":0.018867924528301886,"tutup":0.018867924528301886,"gunakan":0.03773584905660377,"penutup":0.018867924528301886,"steril":0.03773584905660377,"kassa":0.018867924528301886,"memecahkan":0.018867924528301886,"gelembung":0.018867924528301886,"mentega":0.018867924528301886,"odol":0.018867924528301886,"oli":0.018867924528301886,"kecap":0.018867924528301886,"kopi":0.018867924528301886,"rujuk":0.018867924528301886,"fasilitas":0.018867924528301886,"kesehatan":0.018867924528301886}','ACTIVE','2026-09-13 11:56:47','2026-09-13 11:56:47');
INSERT INTO knowledge_chunks VALUES(37,1,8,'Pemindahan Korban','Halaman 37',37,unistr('PEMINDAHAN\u000aKORBAN\u000a37'),'{"pemindahan":0.5,"korban":0.5}','ACTIVE','2026-09-13 11:56:48','2026-09-13 11:56:48');
INSERT INTO knowledge_chunks VALUES(38,1,8,'Pemindahan Korban','Halaman 38',38,unistr('PEMINDAHAN KORBAN\u000aS\u000aetelah melakukan penilaian keadaan dan penilaian dini, selanjutnya kita\u000amenentukan prioritas pemindahan penderita. Beberapa pertanyaan yang\u000amungkin terjadi adalah:\u000aa. Kapan saatnya penderita dipindahkan\u000ab. Apakan penilaian dan pemeriksaan penderita harus selesai sebelum\u000apemindahan\u000ac. Berapa lamakah tulang belakang harus dijaga ( stabilisasi manual )\u000aBeberapa hal yang harus diperhatikan dalam pemindahan\u000apenderita:\u000a1. Nilai kesulitan yang mungkin terjadi pada saat pemindahan\u000a2. Rencanakan gerakan sebelum mengangkat dan memindahkan\u000apenderita\u000a3. Jangan memindahkan dan mengangkat penderita jika tidak mampu\u000a4. Gunakan otot tungkai, panggul serta otot perut. Hindari mengangkat\u000adengan otot punggung dan membungkuk.\u000a5. Jaga keseimbangan\u000a6. Rapatkan tubuh penderita dengan tubuh penolong saat memindahkan\u000adan mengangkat penderita.\u000a7. Perbaiki posisi dan angkatlah secara bertahap\u000aPrinsip dasar pemindahan penderita :\u000a1.\u000a2.\u000a3.\u000aJangan dilakukan jika tidak perlu\u000aMelakukan sesuai dengan cara yang benar\u000aKondisi Fisik Penolong harus baik dan terlatih\u000aTidak ada definisi yang pasti kapan seorang penderita harus dipindahkan.\u000aSebagai pedoman dapat dikatakan bahwa bila tidak ada bahaya berikan\u000apertolongan dulu baru pindahkan penderita. Bila situasi dan kondisi\u000adilapangan relative tidak aman mungkin harus dilakukan pemindahan\u000apenderita terlebih dahulu.\u000a38'),'{"pemindahan":0.051470588235294115,"korban":0.007352941176470588,"etelah":0.007352941176470588,"melakukan":0.014705882352941176,"penilaian":0.022058823529411766,"keadaan":0.007352941176470588,"dini":0.007352941176470588,"selanjutnya":0.007352941176470588,"kita":0.007352941176470588,"menentukan":0.007352941176470588,"prioritas":0.007352941176470588,"penderita":0.0882352941