INSERT INTO knowledge_chunks VALUES(39,1,8,'Pemindahan Korban','Halaman 39',39,unistr('Berdasarkan keselamatan penolong dan penderita, pemindahan penderita\u000adigolongkan menjadi 2 bagian :\u000a1. Pemindahan Darurat\u000aPemindahan darurat dilakukan bila ada bahaya yang mengancam bagi\u000apenderita dan penolong. Contoh :\u000a- Ancaman Kebakaran\u000a- Ancaman Ledakan\u000a- Ancaman Bangunan runtuh\u000a- Ancaman mobil terguling bensin tumpah\u000a- Adanya bahan-bahan berbahaya\u000a- Orang sekitar yang berprilaku aneh\u000a- Kondisi cuaca yang buruk\u000aContoh Cara pemindahan Darurat :\u000a- Tarikan lengan\u000a- Tarikan Bahu\u000a- Tarikan Baju\u000a- Tarikan selimut\u000aBritish Red Cross\u000aBritish Red Cross\u000a39'),'{"berdasarkan":0.01639344262295082,"keselamatan":0.01639344262295082,"penolong":0.03278688524590164,"penderita":0.04918032786885246,"pemindahan":0.06557377049180328,"digolongkan":0.01639344262295082,"menjadi":0.01639344262295082,"bagian":0.01639344262295082,"darurat":0.04918032786885246,"dilakukan":0.01639344262295082,"bila":0.01639344262295082,"bahaya":0.01639344262295082,"mengancam":0.01639344262295082,"bagi":0.01639344262295082,"contoh":0.03278688524590164,"ancaman":0.06557377049180328,"kebakaran":0.01639344262295082,"ledakan":0.01639344262295082,"bangunan":0.01639344262295082,"runtuh":0.01639344262295082,"mobil":0.01639344262295082,"terguling":0.01639344262295082,"bensin":0.01639344262295082,"tumpah":0.01639344262295082,"adanya":0.01639344262295082,"bahan-bahan":0.01639344262295082,"berbahaya":0.01639344262295082,"orang":0.01639344262295082,"sekitar":0.01639344262295082,"berprilaku":0.01639344262295082,"aneh":0.01639344262295082,"kondisi":0.01639344262295082,"cuaca":0.01639344262295082,"buruk":0.01639344262295082,"cara":0.01639344262295082,"tarikan":0.06557377049180328,"lengan":0.01639344262295082,"bahu":0.01639344262295082,"baju":0.01639344262295082,"selimut":0.01639344262295082,"british":0.03278688524590164,"red":0.03278688524590164,