INSERT INTO knowledge_chunks VALUES(40,1,8,'Pemindahan Korban','Halaman 40',40,unistr('2. Pemindahan Biasa\u000aPemindahan biasa dilakukan jika keadaan tidak membahayakan penderita\u000amaupun penolong.\u000aTeknik angkat langsung dengan tiga penolong:\u000a-\u000a40\u000ake tiga penolong berlutut pada salah satu sisi penderita , jika\u000amemungkinkan beradalah pada sisi yang paling sedikit cedera.\u000apenolong pertama menyisipkan satu lengan dibawah leher dan\u000abahu, lengan yang satu disisipkan dibawah punggung penderita.\u000apenolong kedua menyisipkan tangan dibawah punggung dan bokong\u000apenderita.\u000apenolong ketiga menyisipkan lengan dibawah bokong dan dibawah\u000alutut penderita.\u000apenderita siap diangkat dengan satu perintah.\u000aangkat penderita keatas lutut ketiga penolong secara bersamaan.\u000asisipkan tandu yang akan digunakan dan atur letaknya oleh\u000apenolong yang lain.\u000aletakkan kembali penderta diatas tandu dengan satu perintah yang\u000atepat.\u000ajika akan berjalan tampa memakai tandu, dari langkah no 6\u000ateruskan dengan memiringkan penderita ke dada penolong.\u000aberdiri secara bersamaan dengan satu perintah.'),'{"pemindahan":0.0196078431372549,"biasa":0.0196078431372549,"dilakukan":0.00980392156862745,"keadaan":0.00980392156862745,"tidak":0.00980392156862745,"membahayakan":0.00980392156862745,"penderita":0.0784313725490196,"maupun":0.00980392156862745,"penolong":0.08823529411764706,"teknik":0.00980392156862745,"angkat":0.0196078431372549,"langsung":0.00980392156862745,"tiga":0.0196078431372549,"berlutut":0.00980392156862745,"salah":0.00980392156862745,"satu":0.058823529411764705,"sisi":0.0196078431372549,"memungkinkan":0.00980392156862745,"beradalah":0.00980392156862745,"paling":0.00980392156862745,"sedikit":0.00980392156862745,"cedera":0.00980392156862745,"pertama":0.00980392156862745,"menyisipkan":0.029411764705882353,"lengan":0.029411764705882353,"dibawah":0.049019607843137254,"leher":0.00980392156862745,"bahu":0.0098