INSERT INTO knowledge_chunks VALUES(41,1,8,'Pemindahan Korban','Halaman 41',41,unistr('Teknik mengangkat tandu:\u000aPenolong dalam keadaan berjongkok dan akan mengangkat tandu\u000a- Tempatkan kaki pada jarak yang tepat.\u000a- Punggung harus tetap lurus.\u000a- Kencangkan otot punggung dan otot perut. Kepala tetap menghadap\u000akedepan dalam posisi netral.\u000a- Genggamlah pegangan tandu dengan baik.\u000a- Pada saat mengangkat punggung harus tetap terkunci sebagai poros dan\u000akekuatan konstraksi otot seluruhnya pada otot tungkai.\u000a- Saat menurunkan tandu lakukan langkah diatas pada urutan\u000aselanjutnya.\u000a41'),'{"teknik":0.02040816326530612,"mengangkat":0.061224489795918366,"tandu":0.08163265306122448,"penolong":0.02040816326530612,"keadaan":0.02040816326530612,"berjongkok":0.02040816326530612,"tempatkan":0.02040816326530612,"kaki":0.02040816326530612,"jarak":0.02040816326530612,"tepat":0.02040816326530612,"punggung":0.061224489795918366,"tetap":0.061224489795918366,"lurus":0.02040816326530612,"kencangkan":0.02040816326530612,"otot":0.08163265306122448,"perut":0.02040816326530612,"kepala":0.02040816326530612,"menghadap":0.02040816326530612,"kedepan":0.02040816326530612,"posisi":0.02040816326530612,"netral":0.02040816326530612,"genggamlah":0.02040816326530612,"pegangan":0.02040816326530612,"baik":0.02040816326530612,"terkunci":0.02040816326530612,"sebagai":0.02040816326530612,"poros":0.02040816326530612,"kekuatan":0.02040816326530612,"konstraksi":0.02040816326530612,"seluruhnya":0.02040816326530612,"tungkai":0.02040816326530612,"menurunkan":0.02040816326530612,"lakukan":0.02040816326530612,"langkah":0.02040816326530612,"diatas":0.02040816326530612,"urutan":0.02040816326530612,"selanjutnya":0.02040816326530612}','ACTIVE','2026-09-13 11:56:48','2026-09-13 11:56:48');
INSERT INTO knowledge_chunks VALUES(42,1,8,'Pemindahan Korban','Halaman 42',42,unistr('Teknik angkat anggota gerak\u000aBiasanya diperlukan dua penolong untuk melakukan teknik ini :\u000a- Penolong pertama berada diposisi kepala penderita.\u000a- Lakukan pengangkatan pada lengan penderita.\u000a- Penolong yang lain berdiri diantara dua tungkai penderita, menyelipkan\u000atangan dan mengangkat ke dua lutut penderita.\u000a- Dengan satu aba- aba kedua penolong dapat memindahkan penderita di\u000alokasi yang diinginkan.\u000aPosisi penderita\u000aSecara umum posisi penderita tergantung dari cedera yang dialami dan\u000akeadaan pada saat itu. Beberapa pedoman untuk memposisikan penderita :\u000a- Penderita dengan syok. Jika tidak ditemukan tanda-tanda cedera pada\u000atungkai atas dan tulang belakang tingikka tungkai sekitar 20 – 30 cm.\u000a- Penderita dengan gangguan pernapasan. Posisikan duduk atau setengah\u000aduduk.\u000a- Penderita dengan nyeri perut. Posisikan tidur. Posisikan tidur miring\u000adengan tungkai ditekuk.\u000a- Penderita Muntah-muntah. Posisikan nyaman dan awasi jalan napas.\u000a- Penderita Trauma, terutama dicurigai cedera tulang belakang (spinal)\u000aharus segera distabilkan dan imobilisasi dengan papan spinal panjang.\u000a- Penderita tidak sadar dan tidak dicurigai ada cedera spinal atau cedera\u000aberat lainnya, posisikan miring stabil.\u000aPosisi terbaik melakukan pemindahan tergantung pada kondisi saat itu.\u000a42'),'{"teknik":0.016129032258064516,"angkat":0.008064516129032258,"anggota":0.008064516129032258,"gerak":0.008064516129032258,"biasanya":0.008064516129032258,"diperlukan":0.008064516129032258,"penolong":0.03225806451612903,"melakukan":0.016129032258064516,"pertama":0.008064516129032258,"berada":0.008064516129032258,"diposisi":0.008064516129032258,"kepala":0.008064516129032258,"penderita":0.11290322580645161,"lakukan":0.008064516129032258,"pengangkatan":0.008064516129032258,"lengan":0.008064516129032258,"lain":0.00806451612903225