INSERT INTO knowledge_chunks VALUES(45,1,9,'Kedaruratan Medis','Halaman 45',45,unistr('Beberapa kasus umum yang mungkin ditemukan oleh seorang penolong:\u000a1. Pingsan\u000aApakah kamu pernah pingsan? Bagimana rasanya? Atau mungkin kamu\u000apernah melihat orang pingsan. Terus, apakah kamu tau kenapa seseorang\u000abisa pingsan? Berikut ini adalah penjelasannya.\u000aApa penyebab pingsan yang sebenarnya?\u000aPingsan dapat terjadi karena peredaran darah dan oksigen ke organ otak\u000aberkurang.\u000aMisalnya karena :\u000aReaksi terhadap rasa nyeri\u000aKelelahan\u000aKekurangan makanan\u000aEmosi yang hebat\u000aBerada dalam ruangan yang penuh orang tanpa udara segar yang\u000acukup.\u000aWaspadai Pingsan! Waspadai Gejala dan Tandanya!\u000aPerasaan limbung.\u000aPandangan berkunang-kunang dan telinga berdenging.\u000aLemas, keluar keringat dingin.\u000aMenguap.\u000aDapat menjadi tidak ada respon, yang biasanya berlangsung hanya\u000abeberapa menit.\u000aDenyut nadi lambat\u000aCara menangani\u000aBaringkan penderita dengan tungkai ditinggikan.\u000aLonggarkan pakaian.\u000aUsahakan penderita menghirup udara segar.\u000aPeriksa cedera lainnya.\u000aBeri selimut, agar badannya hangat.\u000aBila pulih, usahakan istirahatkan beberapa menit.\u000aBila tidak cepat pulih, maka:\u000a–\u000aPeriksa napas dan nadi.\u000a–\u000aPosisikan stabil.\u000a45'),'{"beberapa":0.024,"kasus":0.008,"umum":0.008,"mungkin":0.016,"ditemukan":0.008,"seorang":0.008,"penolong":0.008,"pingsan":0.056,"apakah":0.016,"kamu":0.024,"pernah":0.016,"bagimana":0.008,"rasanya":0.008,"melihat":0.008,"orang":0.016,"terus":0.008,"tau":0.008,"kenapa":0.008,"seseorang":0.008,"berikut":0.008,"penjelasannya":0.008,"apa":0.008,"penyebab":0.008,"sebenarnya":0.008,"dapat":0.016,"terjadi":0.008,"peredaran":0.008,"darah":0.008,"oksigen":0.008,"organ":0.008,"otak":0.008,"berkurang":0.008,"misalnya":0.008,"reaksi":0.008,"terhadap":0.008,"rasa":0.008,"nyeri":0.008,"kelelahan":0.008,"kekurangan":0.008,"makanan":0.