INSERT INTO knowledge_chunks VALUES(51,1,10,'Keracunan','Halaman 51',51,unistr('2. Keracunan melalui pernapasan\u000aGejala :\u000a- Sesak napas\u000a- Kulit kebiruan (sianosis)\u000a- Napas berbau\u000a- Batuk\u000a- Suara parau\u000aPenanganan :\u000a- Beri oksigen bila ada\u000a- Rujuk ke fasilitas kesehatan segera\u000a3. Keracunan melalui kontak/penyerapan (kulit)\u000aGejala :\u000a- Kulit daerah kontak berwarna kemerahan\u000a- Nyeri\u000a- Melepuh dan meluas\u000aPenanganan :\u000a- Buka baju penderita\u000a- Bila racun berupa serbuk sikat sampai bersih\u000a- Siram bagian yang terkena racun dengan air (minimal 20 Menit)\u000a- Jangan siram kulit dengan air yang terkena soda api\u000a4. Keracunan melalui suntik/gigitan\u000aGejala :\u000a- Luka didaerah suntikan/gigitan\u000a- Nyeri pada daerah gigitan\u000a- Kemerahan\u000a- Perubahan warna kulit\u000aPenanganan :\u000a- Rujuk ke fasilitas kesehatan\u000aWaspadai Keracunan! Gejala dan Tanda Umumnya :\u000a- Penurunan kesadaran, gangguan status mental (gelisah, ketakutan)\u000a- Gangguan pernapasan\u000a- Nyeri kepala, pusing, gangguan penglihatan\u000a- Mual, muntah, mulut berbusa\u000a- Lemas, lumpuh, kesemutan\u000a- Pucat, kebiruan (sianosis)\u000a- Kejang-kejang\u000a- Syok\u000a- Denyut nadi tak beraturan\u000a51'),'{"keracunan":0.034482758620689655,"melalui":0.02586206896551724,"pernapasan":0.017241379310344827,"gejala":0.034482758620689655,"sesak":0.008620689655172414,"napas":0.017241379310344827,"kulit":0.04310344827586207,"kebiruan":0.017241379310344827,"sianosis":0.017241379310344827,"berbau":0.008620689655172414,"batuk":0.008620689655172414,"suara":0.008620689655172414,"parau":0.008620689655172414,"penanganan":0.02586206896551724,"beri":0.008620689655172414,"oksigen":0.008620689655172414,"bila":0.017241379310344827,"rujuk":0.017241379310344827,"fasilitas":0.017241379310344827,"kesehatan":0.017241379310344827,"segera":0.008620689655172414,"kontak":0.017241379310344827,"penyerapan":0.00862068965517