INSERT INTO knowledge_chunks VALUES(52,1,10,'Keracunan','Halaman 52',52,unistr('Gigitan Ular\u000aBila seseorang penderita luka gigitan ular menunjukkan gejala dan tanda\u000amaka berarti keadaannya serius dan perlu penanganan khusus.\u000aBeberapa gejala dan tandanya!\u000a- Demam\u000a- Mual dan muntah\u000a- Pingsan\u000a- Lemah\u000a- Nadi cepat dan lemah\u000a- Kejang\u000a- Gangguan pernapasan\u000aCara menangani gigitan ular\u000a- Amankan diri penolong dan tempat kejadian\u000a- Tenangkan penderita\u000a- Lakukan penilaian dini\u000a- Rawat luka, bila perlu pasang bidai.\u000a- Rujuk ke fasilitas kesehatan\u000aAlternatif lain yang bisa digunakan\u000a- Pemakaian pembalut elastis\u000a- Identifikasi ular bila memungkinkan\u000aJANGAN MEMAKAI TORNIKET\u000a52'),'{"gigitan":0.04411764705882353,"ular":0.058823529411764705,"bila":0.04411764705882353,"seseorang":0.014705882352941176,"penderita":0.029411764705882353,"luka":0.029411764705882353,"menunjukkan":0.014705882352941176,"gejala":0.029411764705882353,"tanda":0.014705882352941176,"maka":0.014705882352941176,"berarti":0.014705882352941176,"keadaannya":0.014705882352941176,"serius":0.014705882352941176,"perlu":0.029411764705882353,"penanganan":0.014705882352941176,"khusus":0.014705882352941176,"beberapa":0.014705882352941176,"tandanya":0.014705882352941176,"demam":0.014705882352941176,"mual":0.014705882352941176,"muntah":0.014705882352941176,"pingsan":0.014705882352941176,"lemah":0.029411764705882353,"nadi":0.014705882352941176,"cepat":0.014705882352941176,"kejang":0.014705882352941176,"gangguan":0.014705882352941176,"pernapasan":0.014705882352941176,"cara":0.014705882352941176,"menangani":0.014705882352941176,"amankan":0.014705882352941176,"diri":0.014705882352941176,"penolong":0.014705882352941176,"tempat":0.014705882352941176,"kejadian":0.014705882352941176,"tenangkan":0.014705882352941176,"lakukan":0.014705882352941176,"penilaian":0.014705882352941176,"dini":0.014705882352941176,"rawat":0.01470588235294117