INSERT INTO knowledge_chunks VALUES(83,2,12,'Breathing Emergencies & Choking','Page 88',88,unistr('Airway and breathing emergencies\u000a\u000aFirst aid for a choking casualty in a wheelchair\u000a\u000a03\u000a\u000aSome wheelchairs will allow the first aider to provide\u000aabdominal or chest thrusts as they would for a casualty who is\u000astanding.\u000aIf you can reach around from behind the wheelchair, give\u000aback blows as normal, and abdominal or chest thrusts.\u000a\u000aIf you cannot reach around the wheelchair, perform the\u000afollowing steps:\u000a1. Position the wheelchair against a wall (if possible) and put\u000athe wheelchair brake on.\u000a2. If possible, carefully lean the casualty forward and sup\u000aport their shoulders. Perform five back blows between the\u000ashoulder blades, using the heel of your hand.\u000a3. Put the heel of one hand, with the other on top, on the\u000acentre of the breastbone and give firm chest thrusts.\u000a\u000a4. Continue giving back blows and chest thrusts until\u000aeither the object is removed or the casualty becomes\u000aunconscious.\u000a88'),'{"airway":0.010101010101010102,"breathing":0.010101010101010102,"emergencies":0.010101010101010102,"first":0.020202020202020204,"aid":0.010101010101010102,"choking":0.010101010101010102,"casualty":0.04040404040404041,"wheelchair":0.050505050505050504,"some":0.010101010101010102,"wheelchairs":0.010101010101010102,"will":0.010101010101010102,"allow":0.010101010101010102,"aider":0.010101010101010102,"provide":0.010101010101010102,"abdominal":0.020202020202020204,"chest":0.04040404040404041,"thrusts":0.04040404040404041,"they":0.010101010101010102,"would":0.010101010101010102,"who":0.010101010101010102,"standing":0.010101010101010102,"you":0.020202020202020204,"can":0.010101010101010102,"reach":0.020202020202020204,"around":0.020202020202020204,"from":0.010101010101010102,"behind":0.010101010101010102,"give":0.020202020202020204,"back":0.030303030303030304,"blows":0.030303030303030304,"normal":0.010101010101010102,"cannot":0.010101010101010102,"perform":0.020202020202020204,"following":0.010101010101010102,"steps":0.010101010101010102,"position":0.010101010101010102,"against":0.010101010101010102,"wall":0.010101010101010102,"possible":0.020202020202020204,"put":0.020202020202020204,"brake":0.010101010101010102,"carefully":0.010101010101010102,"lean":0.010101010101010102,"forward":0.010101010101010102,"sup":0.010101010101010102,"port":0.010101010101010102,"their":0.010101010101010102,"shoulders":0.010101010101010102,"five":0.010101010101010102,"between":0.010101010101010102,"shoulder":0.010101010101010102,"blades":0.010101010101010102,"using":0.010101010101010102,"heel":0.020202020202020204,"your":0.010101010101010102,"hand":0.020202020202020204,"one":0.010101010101010102,"with":0.010101010101010102,"other":0.010101010101010102,"top":0.010101010101010102,"centre":0.010101010101010102,"breastbone":0.010101010101010102,"firm":0.010101010101010102,"continue":0.010101010101010102,"giving":0.010101010101010102,"until":0.010101010101010102,"either":0.010101010101010102,"object":0.010101010101010102,"removed":0.010101010101010102,"becomes":0.010101010101010102,"unconscious":0.010101010101010102}','ACTIVE','2026-09-13 11:56:57','2026-09-13 11:56:57');
INSERT INTO knowledge_chunks VALUES(84,2,12,'Breathing Emergencies & Choking','Page 89',89,unistr('Airway and breathing emergencies\u000a\u000aIf a doctor, physiotherapist, or other health professional has\u000ashown you a different way of giving abdominal thrusts to a\u000aperson in your care, use the recommended method.\u000aIf the casualty becomes unresponsive, you will need to take\u000athem out of the wheelchair.\u000a\u000a03\u000a\u000aFirst aid for a casualty who goes unresponsive\u000aIf the casualty becomes unresponsive while providing first aid\u000afor choking, use a modified CPR approach.\u000a\u000a1. Ease the casualty to the ground if you can do so without\u000ahurting yourself. At minimum, protect their head as they\u000acollapse.\u000a2. Call for medical help and get an AED if available.\u000a3. Give 30 chest compressions in the centre of their chest.\u000a4. Open their airway using the head-tilt/chin-lift and check\u000atheir mouth.\u000a5. Remove any foreign object you can see.\u000a6. Try to give 2 ventilations even if you did not find anything\u000ain their mouth.\u000a\u000a89'),'{"airway":0.019417475728155338,"breathing":0.009708737864077669,"emergencies":0.009708737864077669,"doctor":0.009708737864077669,"physiotherapist":0.009708737864077669,"other":0.009708737864077669,"health":0.009708737864077669,"professional":0.009708737864077669,"has":0.009708737864077669,"shown":0.009708737864077669,"you":0.04854368932038835,"different":0.009708737864077669,"way":0.009708737864077669,"giving":0.009708737864077669,"abdominal":0.009708737864077669,"thrusts":0.009708737864077669,"person":0.009708737864077669,"your":0.009708737864077669,"care":0.009708737864077669,"use":0.019417475728155338,"recommended":0.009708737864077669,"method":0.009708737864077669,"casualty":0.038834951456310676,"becomes":0.019417475728155338,"unresponsive":0.02912621359223301,"will":0.009708737864077669,"need":0.009708737864077669,"take":0.009708737864077669,"them":0.0097087378640