INSERT INTO knowledge_chunks VALUES(85,2,12,'Breathing Emergencies & Choking','Page 90',90,unistr('Airway and breathing emergencies\u000a\u000a03\u000a\u000a7. If the ventilations do not go in, readjust their head. This\u000amay be an indication that you may not have opened the\u000aairway properly the first time.\u000a8. Attempt to give 2 ventilations.\u000a9. If the ventilations still do not go in, resume compressions,\u000amouth checks, and attempts to ventilate.\u000aOnce a ventilation is successful, deliver a second ventilation.\u000aBe ready to continue CPR if the casualty does not start\u000abreathing on their own.\u000aIf the casualty is a child, begin with one hand when giving\u000acompressions. If you are not able to compress the chest\u000aenough, use two hands.\u000a\u000aFirst aid if you are alone and choking\u000aIf you begin to choke on an object, you may have to clear\u000ayour own airway. If there are people around, get their\u000aattention. Do not isolate yourself from others.\u000aTry to cough up the object. If you cannot cough, speak, or\u000abreathe, give yourself abdominal thrusts:\u000a\u000a1. Place the fist of one hand just above your bellybutton.\u000a2. Use your other hand to thrust inward and upward.\u000a3. Repeat until the object is cleared or you can cough or\u000abreathe.\u000a4. Use a solid object like the back of a chair, a table, or the\u000aedge of a counter.\u000a5. Position yourself so the object is just above your hips.\u000a90'),'{"airway":0.02040816326530612,"breathing":0.013605442176870748,"emergencies":0.006802721088435374,"ventilations":0.02040816326530612,"not":0.04081632653061224,"readjust":0.006802721088435374,"their":0.02040816326530612,"head":0.006802721088435374,"this":0.006802721088435374,"may":0.02040816326530612,"indication":0.006802721088435374,"you":0.047619047619047616,"have":0.013605442176870748,"opened":0.006802721088435374,"properly":0.006802721088435374,"first":0.013605442176870748,"time":0.006802721088435374,"attempt":0.006802721088435374,"give":0.013605442176870748,"still":0.006802721088435374,"resume":0.006802721088435374,"compressions":0.013605442176870748,"mouth":0.006802721088435374,"checks":0.006802721088435374,"attempts":0.006802721088435374,"ventilate":0.006802721088435374,"once":0.006802721088435374,"ventilation":0.013605442176870748,"successful":0.006802721088435374,"deliver":0.006802721088435374,"second":0.006802721088435374,"ready":0.006802721088435374,"continue":0.006802721088435374,"cpr":0.006802721088435374,"casualty":0.013605442176870748,"does":0.006802721088435374,"start":0.006802721088435374,"own":0.013605442176870748,"child":0.006802721088435374,"begin":0.013605442176870748,"with":0.006802721088435374,"one":0.013605442176870748,"hand":0.02040816326530612,"when":0.006802721088435374,"giving":0.006802721088435374,"are":0.02040816326530612,"able":0.006802721088435374,"compress":0.006802721088435374,"chest":0.006802721088435374,"enough":0.006802721088435374,"use":0.02040816326530612,"two":0.006802721088435374,"hands":0.006802721088435374,"aid":0.006802721088435374,"alone":0.006802721088435374,"choking":0.006802721088435374,"choke":0.006802721088435374,"object":0.034013605442176874,"clear":0.006802721088435374,"your":0.027210884353741496,"there":0.006802721088435374,"people":0.006802721088435374,"around":0.006802721088435374,"get":0.006802721088435374,"attention":0.006802721088435374,"isolate":0.006802721088435374,"yourself":0.02040816326530612,"from":0.006802721088435374,"others":0.006802721088435374,"try":0.006802721088435374,"cough":0.02040816326530612,"cannot":0.006802721088435374,"speak":0.006802721088435374,"breathe":0.013605442176870748,"abdominal":0.006802721088435374,"thrusts":0.006802721088435374,"place":0.006802721088435374,"fist":0.006802721088435374,"just":0.013605442176870748,"above":0.013605442176870748,"bellybutton":0.006802721088435374,"other":0.006802721088435374,"thrust":0.006802721088435374,"inward":0.006802721088435374,"upward":0.006802721088435374,"repeat":0.006802721088435374,"until":0.006802721088435374,"cleared":0.006802721088435374,"can":0.006802721088435374,"solid":0.006802721088435374,"like":0.006802721088435374,"back":0.006802721088435374,"chair":0.006802721088435374,"table":0.006802721088435374,"edge":0.006802721088435374,"counter":0.006802721088435374,"position":0.006802721088435374,"hips":0.006802721088435374}','ACTIVE','2026-09-13 11:56:57','2026-09-13 11:56:57');
INSERT INTO knowledge_chunks VALUES(86,2,12,'Breathing Emergencies & Choking','Page 91',91,unistr('Airway and breathing emergencies\u000a\u000a6. Press forcefully to produce an abdominal thrust.\u000a\u000a03\u000a\u000aManaging a Choking Emergency for Infants\u000aInfants are at risk for choking since they are frequently putting\u000athings into their mouths. A choking infant will show some or\u000aall of the following signs:\u000a\u000a\u000a\u000a\u000a\u000a\u000aHigh-pitched wheezing or no sound at all\u000aGagging\u000aAppearance of crying with no sound\u000aWide eyes\u000aChanging colour\u000a\u000aFirst aid for a choking infant who is responsive\u000aTo give first aid for a choking infant who is responsive,\u000aperform the following steps:\u000a1. Perform a scene survey and primary survey.\u000a2. Support the infant’s head using a C grip around their chin.\u000a3. Place the infant face down on your forearm with their legs\u000aon either side of your arm.\u000a\u000a91'),'{"airway":0.011363636363636364,"breathing":0.011363636363636364,"emergencies":0.011363636363636364,"press":0.011363636363636364,"forcefully":0.011363636363636364,"produce":0.011363636363636364,"abdominal":0.011363636363636364,"thrust":0.011363636363636364,"managing":0.011363636363636364,"choking":0.056818181818181816,"emergency":0.011363636363636364,"infants":0.022727272727272728,"are":0.022727272727272728,"risk":0.011363636363636364,"since":0.011363636363636364,"they":0.011363636363636364,"frequently":0.011363636363636364,"putting":0.011363636363636364,"things":0.011363636363636364,"into":0.011363636363636364,"their":0.03409090909090909,"mouths":0.011363636363636364,"infant":0.056818181818181816,"will":0.011363636363636364,"show":0.011363636363636364,"some":0.011363636363636364,"all":0.022727272727272728,"following":0.022727272727272728,"signs":0.011363636363636364,"high-pitched":0.011363636363636364,"wheezing":0.011363636363636364,"sound":0.022727272727272728,"gagging":0.011363636363636364,"appearance":0.011363636363636364,"crying":0.011363636363636364,"with":0.022727272727272728,"wide":0.011363636363636364,"eyes":0.011363636363636364,"changing":0.011363636363636364,"colour":0.011363636363636364,"first":0.022727272727272728,"aid":0.022727272727272728,"who":0.022727272727272728,"responsive":0.022727272727272728,"give":0.011363636363636364,"perform":0.022727272727272728,"steps":0.011363636363636364,"scene":0.011363636363636364,"survey":0.022727272727272728,"primary":0.011363636363636364,"support":0.011363636363636364,"head":0.011363636363636364,"using":0.011363636363636364,"grip":0.011363636363636364,"around":0.011363636363636364,"chin":0.011363636363636364,"place":0.011363636363636364,"face":0.011363636363636364,"down":0.011363636363636364,"your":0.022727272727272728,"forearm":0.011363636363636364,"legs":0.011363636363636364,"either":0.011363636363636364,"side":0.011363636363636364,"arm":0.011363636363636364}','ACTIVE','2026-09-13 11:56:57','2026-09-13 11:56:57');
INSERT INTO knowledge_chunks VALUES(87,2,12,'Breathing Emergencies & Choking','Page 92',92,unistr('Airway and breathing emergencies\u000a\u000a03\u000a\u000a4. With the infant’s head lower than their body, use the heel\u000aof your hand to give five forceful back blows between\u000atheir shoulder blades.\u000a5. Use your other arm and hold the infant between your fore\u000aarms, supporting the back of the infant’s head.\u000a6. Turn the infant face up.\u000a\u000a7. Give five chest thrusts using 2 fingers just below their\u000anipple line.\u000aKeep giving back blows and chest thrusts until their airway is\u000acleared or the infant becomes unresponsive. An infant who\u000achokes needs to be seen by a doctor.\u000a\u000aFirst aid for a choking infant who becomes\u000aunresponsive\u000aIf the infant becomes unresponsive, place them on a firm, flat\u000asurface and perform the following steps:\u000a1. Send someone to call 9-1-1 or call yourself and place the\u000aphone on speaker mode.\u000a\u000a92'),'{"airway":0.02040816326530612,"breathing":0.01020408163265306,"emergencies":0.01020408163265306,"with":0.01020408163265306,"infant":0.08163265306122448,"head":0.02040816326530612,"lower":0.01020408163265306,"than":0.01020408163265306,"their":0.04081632653061224,"body":0.01020408163265306,"use":0.02040816326530612,"heel":0.01020408163265306,"your":0.030612244897959183,"hand":0.01020408163265306,"give":0.02040816326530612,"five":0.02040816326530612,"forceful":0.01020408163265306,"back":0.030612244897959183,"blows":0.02040816326530612,"between":0.02040816326530612,"shoulder":0.01020408163265306,"blades":0.01020408163265306,"other":0.01020408163265306,"arm":0.01020408163265306,"hold":0.01020408163265306,"fore":0.01020408163265306,"arms":0.01020408163265306,"supporting":0.01020408163265306,"turn":0.01020408163265306,"face":0.01020408163265306,"chest":0.02040816326530612,"thrusts":0.02040816326530612,"using":0.01020408163265306,"fingers":0.01020408163265306,"just":0.01020408163265306,"below":0.01020408163265306,"nipple":0.01020408163265306,"line":0.01020408163265306,"keep":0.01020408163265306,"giving":0.01020408163265306,"until":0.01020408163265306,"cleared":0.01020408163265306,"becomes":0.030612244897959183,"unresponsive":0.030612244897959183,"who":0.02040816326530612,"chokes":0.01020408163265306,"needs":0.01020408163265306,"seen":0.01020408163265306,"doctor":0.01020408163265306,"first":0.01020408163265306,"aid":0.01020408163265306,"choking":0.01020408163265306,"place":0.02040816326530612,"them":0.01020408163265306,"firm":0.01020408163265306,"flat":0.01020408163265306,"surface":0.01020408163265306,"perform":0.01020408163265306,"following":0.01020408163265306,"steps":0.01020408163265306,"send":0.01020408163265306,"someone":0.01020408163265306,"call":0.02040816326530612,"9-1-1":0.01020408163265306,"yourself":0.01020408163265306,"phone":0.01020408163265306,"speaker":0.01020408163265306,"mode":0.01020408163265306}','ACTIVE','2026-09-13 11:56:57','2026-09-13 11:56:57');
INSERT INTO knowledge_chunks VALUES(88,2,12,'Breathing Emergencies & Choking','Page 93',93,unistr('Airway and breathing emergencies\u000a\u000a2. Using two fingers below the infant s nipple line, deliver 30\u000acompressions. Open their airway using the head-tilt/chinlift and check their mouth.\u000a\u000a03\u000a\u000a3. Remove any foreign object you can see.\u000a4. Try to give 2 ventilations even if you did not find anything\u000ain their mouth.\u000a5. If the ventilations do not go in, readjust their head. This\u000amay be an indication that you may not have opened the\u000aairway properly the first time.\u000a6. Attempt to give 2 ventilations.\u000a7. If the ventilations still do not go in, resume compressions,\u000amouth checks, and attempts to ventilate.\u000aAn infant s lungs are much smaller than those of an adult.\u000aWhen giving ventilations, do not blow forcefully, and only\u000agive enough for the chest to rise (often described as a cheekfull of air).\u000aBecause an infant’s head is larger than their body\u000aproportionally, you may need to place a folded towel or\u000ablanket under their shoulders to allow for a proper head-tilt.\u000a\u000a93'),'{"airway":0.026785714285714284,"breathing":0.008928571428571428,"emergencies":0.008928571428571428,"using":0.017857142857142856,"two":0.008928571428571428,"fingers":0.008928571428571428,"below":0.008928571428571428,"infant":0.026785714285714284,"nipple":0.008928571428571428,"line":0.008928571428571428,"deliver":0.008928571428571428,"compressions":0.017857142857142856,"open":0.008928571428571428,"their":0.05357142857142857,"head-tilt":0.017857142857142856,"chinlift":0.008928571428571428,"check":0.008928571428571428,"mouth":0.026785714285714284,"remove":0.008928571428571428,"any":0.008928571428571428,"foreign":0.008928571428571428,"object":0.008928571428571428,"you":0.03571428571428571,"can":0.008928571428571428,"see":0.008928571428571428,"try":0.008928571428571428,"give":0.026785714285714284,"ventilations":0.044642857142857144,"even":0.008928571428571428,"did":0.008928571428571428,"not":0.044642857142857144,"find":0.008928571428571428,"anything":0.008928571428571428,"readjust":0.008928571428571428,"head":0.017857142857142856,"this":0.008928571428571428,"may":0.026785714285714284,"indication":0.008928571428571428,"have":0.008928571428571428,"opened":0.008928571428571428,"properly":0.008928571428571428,"first":0.008928571428571428,"time":0.008928571428571428,"attempt":0.008928571428571428,"still":0.008928571428571428,"resume":0.008928571428571428,"checks":0.008928571428571428,"attempts":0.008928571428571428,"ventilate":0.008928571428571428,"lungs":0.008928571428571428,"are":0.008928571428571428,"much":0.008928571428571428,"smaller":0.008928571428571428,"than":0.017857142857142856,"those":0.008928571428571428,"adult":0.008928571428571428,"when":0.008928571428571428,"giving":0.008928571428571428,"blow":0.008928571428571428,"forcefully":0.008928571428571428,"only":0.008928571428571428,"enough":0.008928571428571428,"chest":0.008928571428571428,"rise":0.008928571428571428,"often":0.008928571428571428,"described":0.008928571428571428,"cheekfull":0.008928571428571428,"air":0.008928571428571428,"because":0.008928571428571428,"larger":0.008928571428571428,"body":0.008928571428571428,"proportionally":0.008928571428571428,"need":0.008928571428571428,"place":0.008928571428571428,"folded":0.008928571428571428,"towel":0.008928571428571428,"blanket":0.008928571428571428,"under":0.008928571428571428,"shoulders":0.008928571428571428,"allow":0.008928571428571428,"proper":0.008928571428571428}','ACTIVE','2026-09-13 11:56:58','2026-09-13 11:56:58');
