INSERT INTO knowledge_chunks VALUES(93,2,12,'Breathing Emergencies & Choking','Page 98',98,unistr('Cardiovascular emergencies\u000a\u000aANGINA AND HEART ATTACK\u000a\u000a04\u000a\u000aAngina occurs when the heart muscle is not properly supplied\u000awith oxygenated blood due to narrowed, damaged or\u000ablocked arteries in the heart. When the heart works harder\u000aand needs more blood (e.g., when you run for a bus or shovel\u000asnow), it cannot get enough blood. This causes pain or\u000adiscomfort in the chest, which may spread to the neck, jaw,\u000ashoulders, and arms. Angina pain typically doesn t last long\u000aand goes away if the person rests and takes their prescribed\u000amedication.\u000aA heart attack (or myocardial infarction) occurs when heart\u000amuscle tissue dies because its supply of blood has been cut\u000aoff. A heart attack can feel just like angina, except the pain\u000adoesn t go away with rest and medication.\u000aIf the heart attack damages the heart’s electrical system, or\u000aif a lot of the heart muscle is affected, the heart may stop\u000abeating properly. This is cardiac arrest.\u000a\u000a98'),'{"cardiovascular":0.008695652173913044,"emergencies":0.008695652173913044,"angina":0.034782608695652174,"heart":0.09565217391304348,"attack":0.034782608695652174,"occurs":0.017391304347826087,"when":0.034782608695652174,"muscle":0.02608695652173913,"not":0.008695652173913044,"properly":0.017391304347826087,"supplied":0.008695652173913044,"with":0.017391304347826087,"oxygenated":0.008695652173913044,"blood":0.034782608695652174,"due":0.008695652173913044,"narrowed":0.008695652173913044,"damaged":0.008695652173913044,"blocked":0.008695652173913044,"arteries":0.008695652173913044,"works":0.008695652173913044,"harder":0.008695652173913044,"needs":0.008695652173913044,"more":0.008695652173913044,"you":0.008695652173913044,"run":0.008695652173913044,"bus":0.008695652173913044,"shovel":0.008695652173913044,"snow":0.008695652173913044,"cannot":0.008695652173913044,"get":0.008695652173913044,"enough":0.008695652173913044,"this":0.017391304347826087,"causes":0.008695652173913044,"pain":0.02608695652173913,"discomfort":0.008695652173913044,"chest":0.008695652173913044,"which":0.008695652173913044,"may":0.017391304347826087,"spread":0.008695652173913044,"neck":0.008695652173913044,"jaw":0.008695652173913044,"shoulders":0.008695652173913044,"arms":0.008695652173913044,"typically":0.008695652173913044,"doesn":0.017391304347826087,"last":0.008695652173913044,"long":0.008695652173913044,"goes":0.008695652173913044,"away":0.017391304347826087,"person":0.008695652173913044,"rests":0.008695652173913044,"takes":0.008695652173913044,"their":0.008695652173913044,"prescribed":0.008695652173913044,"medication":0.017391304347826087,"myocardial":0.008695652173913044,"infarction":0.008695652173913044,"tissue":0.008695652173913044,"dies":0.008695652173913044,"because":0.008695652173913044,"its":0.008695652173913044,"supply":0.008695652173913044,"has":0.008695652173913044,"been":0.008695652173913044,"cut":0.008695652173913044,"off":0.008695652173913044,"can":0.008695652173913044,"feel":0.008695652173913044,"just":0.008695652173913044,"like":0.008695652173913044,"except":0.008695652173913044,"rest":0.008695652173913044,"damages":0.008695652173913044,"electrical":0.008695652173913044,"system":0.008695652173913044,"lot":0.008695652173913044,"affected":0.008695652173913044,"stop":0.008695652173913044,"beating":0.008695652173913044,"cardiac":0.008695652173913044,"arrest":0.008695652173913044}','ACTIVE','2026-09-13 11:56:59','2026-09-13 11:56:59');
INSERT INTO knowledge_chunks VALUES(94,2,12,'Breathing Emergencies & Choking','Page 99',99,unistr('Cardiovascular emergencies\u000a\u000aRisk Factors\u000aSeveral factors increase the risks for cardiovascular disease,\u000aheart attack, and stroke. These can be broken down into\u000amodifiable and non-modifiable risks.\u000a\u000a04\u000a\u000aRisk Factors\u000aModifiable\u000a\u000aNon-Modifiable\u000a\u000aSmoking\u000aPoor diet\u000aLack of exercise\u000aIncreased stress\u000aAge\u000aGenetic history\u000aSex assigned at birth\u000a\u000aThe modifiable risk factors can lead to dyslipidemia\u000a(increased deposits of fats), obesity, diabetes, and high blood\u000apressure. These modifiable risks can be reduced through\u000alifestyle changes.\u000a\u000a99'),'{"cardiovascular":0.03333333333333333,"emergencies":0.016666666666666666,"risk":0.05,"factors":0.06666666666666667,"several":0.016666666666666666,"increase":0.016666666666666666,"risks":0.05,"disease":0.016666666666666666,"heart":0.016666666666666666,"attack":0.016666666666666666,"stroke":0.016666666666666666,"these":0.03333333333333333,"can":0.05,"broken":0.016666666666666666,"down":0.016666666666666666,"into":0.016666666666666666,"modifiable":0.06666666666666667,"non-modifiable":0.03333333333333333,"smoking":0.016666666666666666,"poor":0.016666666666666666,"diet":0.016666666666666666,"lack":0.016666666666666666,"exercise":0.016666666666666666,"increased":0.03333333333333333,"stress":0.016666666666666666,"age":0.016666666666666666,"genetic":0.016666666666666666,"history":0.016666666666666666,"sex":0.016666666666666666,"assigned":0.016666666666666666,"birth":0.016666666666666666,"lead":0.016666666666666666,"dyslipidemia":0.016666666666666666,"deposits":0.016666666666666666,"fats":0.016666666666666666,"obesity":0.016666666666666666,"diabetes":0.016666666666666666,"high":0.016666666666666666,"blood":0.016666666666666666,"pressure":0.016666666666666666,"reduced":0.016666666666666666,"through":0.016666666666666666,"lifestyle":0.016666666666666666,"changes":0.016666666666666666}','ACTIVE','2026-09-13 11:56:59','2026-09-13 11:56:59');
INSERT INTO knowledge_chunks VALUES(95,2,13,'Cardiac Arrest & CPR Protocols','Page 113',113,unistr('CPR and AED\u000a\u000aPerforming Two-Rescuer CPR\u000aIf two trained rescuers are available, they can cooperate to\u000aperform CPR on a casualty. There are three advantages to two\u000arescuers performing CPR as a team:\u000a CPR is a strenuous physical activity and as a first aider\u000agets tired, the quality of the chest compressions will\u000adeteriorate. By sharing the task of compressing the chest,\u000atwo rescuer CPR allows a team to perform effective chest\u000acompressions for a longer period.\u000a Two-rescuer CPR minimizes the time the compressions are\u000ainterrupted for ventilations to be given.\u000a Two-rescuer CPR allows the rescuers to give feedback and\u000asupport each other during a stressful event.\u000aTo perform two-rescuer CPR, the first aider who performs\u000athe primary survey stays at the casualty’s head, keeping\u000athe airway open and ventilating after 30 compressions. The\u000asecond rescuer will compress the chest.\u000aTo maintain effective compressions, it is recommended that\u000arescuers switch roles after every 5 cycles of compressions and\u000aventilations (approximately 2 minutes).\u000a\u000aCHILD CPR\u000aOne-rescuer CPR for a child is the same as for an adult,\u000aexcept for adjusting to accommodate the smaller size. Use\u000aone hand for CPR unless you are not able to compress the\u000achest sufficiently. The amount of air required to make the\u000achest rise will be less than for an adult.\u000aTwo-rescuer CPR for a child changes the compression to\u000aventilation ratio. When a child goes into cardiac arrest,\u000atypically it is due to a breathing issue, whereas for an adult\u000ait is typically a heart issue. In addition, a child requires more\u000a113\u000a\u000a05'),'{"113":0.005813953488372093,"cpr":0.0755813953488372,"aed":0.005813953488372093,"performing":0.011627906976744186,"two-rescuer":0.029069767441860465,"two":0.01744186046511628,"trained":0.005813953488372093,"rescuers":0.023255813953488372,"are":0.023255813953488372,"available":0.005813953488372093,"they":0.005813953488372093,"can":0.005813953488372093,"cooperate":0.005813953488372093,"perform":0.01744186046511628,"casualty":0.011627906976744186,"there":0.005813953488372093,"three":0.005813953488372093,"advantages":0.005813953488372093,"team":0.011627906976744186,"strenuous":0.005813953488372093,"physical":0.005813953488372093,"activity":0.005813953488372093,"first":0.011627906976744186,"aider":0.011627906976744186,"gets":0.005813953488372093,"tired":0.005813953488372093,"quality":0.005813953488372093,"chest":0.03488372093023256,"compressions":0.03488372093023256,"will":0.01744186046511628,"deteriorate":0.005813953488372093,"sharing":0.005813953488372093,"task":0.005813953488372093,"compressing":0.005813953488372093,"rescuer":0.011627906976744186,"allows":0.011627906976744186,"effective":0.011627906976744186,"longer":0.005813953488372093,"period":0.005813953488372093,"minimizes":0.005813953488372093,"time":0.005813953488372093,"interrupted":0.005813953488372093,"ventilations":0.011627906976744186,"given":0.005813953488372093,"give":0.005813953488372093,"feedback":0.005813953488372093,"support":0.005813953488372093,"each":0.005813953488372093,"other":0.005813953488372093,"during":0.005813953488372093,"stressful":0.005813953488372093,"event":0.005813953488372093,"who":0.005813953488372093,"performs":0.005813953488372093,"primary":0.005813953488372093,"survey":0.005813953488372093,"stays":0.005813953488372093,"head":0.005813953488372093,"keeping":0.005813953488372093,"airway":0.005813953488372093,"open":0.005813953488372093,"ventilating":0.005813953488372093,"after":0.011627906976744186,"second":0.005813953488372093,"compress":0.011627906976744186,"maintain":0.005813953488372093,"recommended":0.005813953488372093,"switch":0.005813953488372093,"roles":0.005813953488372093,"every":0.005813953488372093,"cycles":0.005813953488372093,"approximately":0.005813953488372093,"minutes":0.005813953488372093,"child":0.029069767441860465,"one-rescuer":0.005813953488372093,"same":0.005813953488372093,"adult":0.01744186046511628,"except":0.005813953488372093,"adjusting":0.005813953488372093,"accommodate":0.005813953488372093,"smaller":0.005813953488372093,"size":0.005813953488372093,"use":0.005813953488372093,"one":0.005813953488372093,"hand":0.005813953488372093,"unless":0.005813953488372093,"you":0.005813953488372093,"not":0.005813953488372093,"able":0.005813953488372093,"sufficiently":0.005813953488372093,"amount":0.005813953488372093,"air":0.005813953488372093,"required":0.005813953488372093,"make":0.005813953488372093,"rise":0.005813953488372093,"less":0.005813953488372093,"than":0.005813953488372093,"changes":0.005813953488372093,"compression":0.005813953488372093,"ventilation":0.005813953488372093,"ratio":0.005813953488372093,"when":0.005813953488372093,"goes":0.005813953488372093,"into":0.005813953488372093,"cardiac":0.005813953488372093,"arrest":0.005813953488372093,"typically":0.011627906976744186,"due":0.005813953488372093,"breathing":0.005813953488372093,"issue":0.011627906976744186,"whereas":0.005813953488372093,"heart":0.005813953488372093,"addition":0.005813953488372093,"requires":0.005813953488372093,"more":0.005813953488372093}','ACTIVE','2026-09-13 11:56:59','2026-09-13 11:56:59');
INSERT INTO knowledge_chunks VALUES(96,2,13,'Cardiac Arrest & CPR Protocols','Page 114',114,unistr('CPR and AED\u000a\u000a05\u000a\u000aoxygen on average than an adult does, and in an ideal\u000asituation, CPR for a child would have breaths delivered\u000aevery 15 compressions. However, the time it takes to stop\u000acompressions, move to the head, deliver the breaths, and\u000areturn to the chest is too long. When there are two rescuers,\u000athat time can be cut down significantly, by stopping at 15\u000acompressions to give 2 breaths. This helps to deliver more\u000aoxygenated blood to the vital organs and provides the child\u000awith a better chance of survival.\u000a\u000aPerforming One-Rescuer Child CPR\u000aTo carry out one-rescuer child CPR, perform the following steps:\u000a1. Perform a scene survey.\u000aa. Assess responsiveness.\u000ab. Send someone to call 9-1-1 and get an AED if\u000aavailable.\u000a2. Perform a primary survey.\u000aa. Open the airway.\u000ab. Check for breathing for at least 5 and no more\u000athan 10 seconds.\u000a\u000a114'),'{"114":0.010638297872340425,"cpr":0.0425531914893617,"aed":0.02127659574468085,"oxygen":0.010638297872340425,"average":0.010638297872340425,"than":0.02127659574468085,"adult":0.010638297872340425,"does":0.010638297872340425,"ideal":0.010638297872340425,"situation":0.010638297872340425,"child":0.0425531914893617,"would":0.010638297872340425,"have":0.010638297872340425,"breaths":0.031914893617021274,"delivered":0.010638297872340425,"every":0.010638297872340425,"compressions":0.031914893617021274,"however":0.010638297872340425,"time":0.02127659574468085,"takes":0.010638297872340425,"stop":0.010638297872340425,"move":0.010638297872340425,"head":0.010638297872340425,"deliver":0.02127659574468085,"return":0.010638297872340425,"chest":0.010638297872340425,"too":0.010638297872340425,"long":0.010638297872340425,"when":0.010638297872340425,"there":0.010638297872340425,"are":0.010638297872340425,"two":0.010638297872340425,"rescuers":0.010638297872340425,"can":0.010638297872340425,"cut":0.010638297872340425,"down":0.010638297872340425,"significantly":0.010638297872340425,"stopping":0.010638297872340425,"give":0.010638297872340425,"this":0.010638297872340425,"helps":0.010638297872340425,"more":0.02127659574468085,"oxygenated":0.010638297872340425,"blood":0.010638297872340425,"vital":0.010638297872340425,"organs":0.010638297872340425,"provides":0.010638297872340425,"with":0.010638297872340425,"better":0.010638297872340425,"chance":0.010638297872340425,"survival":0.010638297872340425,"performing":0.010638297872340425,"one-rescuer":0.02127659574468085,"carry":0.010638297872340425,"out":0.010638297872340425,"perform":0.031914893617021274,"following":0.010638297872340425,"steps":0.010638297872340425,"scene":0.010638297872340425,"survey":0.02127659574468085,"assess":0.010638297872340425,"responsiveness":0.010638297872340425,"send":0.010638297872340425,"someone":0.010638297872340425,"call":0.010638297872340425,"9-1-1":0.010638297872340425,"get":0.010638297872340425,"available":0.010638297872340425,"primary":0.010638297872340425,"open":0.010638297872340425,"airway":0.010638297872340425,"check":0.010638297872340425,"breathing":0.010638297872340425,"least":0.010638297872340425,"seconds":0.010638297872340425}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(97,2,13,'Cardiac Arrest & CPR Protocols','Page 115',115,unistr('CPR and AED\u000a\u000a3. If the casualty is not breathing, or not breathing effectively (agonal breaths), begin compressions immediately.\u000a4. Give 30 compressions. Push hard. Push fast.\u000a5. Position one hand in the centre of the upper chest with\u000ayour shoulder directly over your hand, and keep the\u000aelbow locked.\u000a\u000a05\u000a\u000aa. Place your other hand behind your back, or on the\u000aground above the child’s head.\u000ab. Press the heel of the hand straight down on the\u000abreastbone. The depth of each compression\u000ashould be 1/3 the depth of the chest.\u000ac. Release pressure and completely remove your\u000aweight at the top of each compression to allow\u000athe chest to return to the resting position.\u000ad. Give compressions at a rate of 100 to 120 per\u000aminute. Count compressions out loud to keep\u000atrack of how many you have given, and to help\u000akeep a steady rhythm.\u000a6. Open their airway using a head-tilt/chin-lift.\u000a7. Position a barrier device and give 2 ventilations.\u000aa. For a child casualty, each breath should take less\u000athan 1 second, with just enough air to make the\u000achest rise.\u000a\u000a115'),'{"100":0.00819672131147541,"115":0.00819672131147541,"120":0.00819672131147541,"cpr":0.00819672131147541,"aed":0.00819672131147541,"casualty":0.01639344262295082,"not":0.01639344262295082,"breathing":0.01639344262295082,"effectively":0.00819672131147541,"agonal":0.00819672131147541,"breaths":0.00819672131147541,"begin":0.00819672131147541,"compressions":0.03278688524590164,"immediately":0.00819672131147541,"give":0.02459016393442623,"push":0.01639344262295082,"hard":0.00819672131147541,"fast":0.00819672131147541,"position":0.02459016393442623,"one":0.00819672131147541,"hand":0.03278688524590164,"centre":0.00819672131147541,"upper":0.00819672131147541,"chest":0.03278688524590164,"with":0.01639344262295082,"your":0.040983606557377046,"shoulder":0.00819672131147541,"directly":0.00819672131147541,"over":0.00819672131147541,"keep":0.02459016393442623,"elbow":0.00819672131147541,"locked":0.00819672131147541,"place":0.00819672131147541,"other":0.00819672131147541,"behind":0.00819672131147541,"back":0.00819672131147541,"ground":0.00819672131147541,"above":0.00819672131147541,"child":0.01639344262295082,"head":0.00819672131147541,"press":0.00819672131147541,"heel":0.00819672131147541,"straight":0.00819672131147541,"down":0.00819672131147541,"breastbone":0.00819672131147541,"depth":0.01639344262295082,"each":0.02459016393442623,"compression":0.01639344262295082,"should":0.01639344262295082,"release":0.00819672131147541,"pressure":0.00819672131147541,"completely":0.00819672131147541,"remove":0.00819672131147541,"weight":0.00819672131147541,"top":0.00819672131147541,"allow":0.00819672131147541,"return":0.00819672131147541,"resting":0.00819672131147541,"rate":0.00819672131147541,"per":0.00819672131147541,"minute":0.00819672131147541,"count":0.00819672131147541,"out":0.00819672131147541,"loud":0.00819672131147541,"track":0.00819672131147541,"how":0.00819672131147541,"many":0.00819672131147541,"you":0.00819672131147541,"have":0.00819672131147541,"given":0.00819672131147541,"help":0.00819672131147541,"steady":0.00819672131147541,"rhythm":0.00819672131147541,"open":0.00819672131147541,"their":0.00819672131147541,"airway":0.00819672131147541,"using":0.00819672131147541,"head-tilt":0.00819672131147541,"chin-lift":0.00819672131147541,"barrier":0.00819672131147541,"device":0.00819672131147541,"ventilations":0.00819672131147541,"breath":0.00819672131147541,"take":0.00819672131147541,"less":0.00819672131147541,"than":0.00819672131147541,"second":0.00819672131147541,"just":0.00819672131147541,"enough":0.00819672131147541,"air":0.00819672131147541,"make":0.00819672131147541,"rise":0.00819672131147541}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(98,2,13,'Cardiac Arrest & CPR Protocols','Page 116',116,unistr('CPR and AED\u000a\u000aThis is one cycle of 30:2 (30 compressions to 2 ventilations).\u000a\u000a05\u000a\u000a8. Continue CPR until:\u000aa. An AED is applied.\u000ab. The casualty begins to respond.\u000ac. Another first aider or medical help takes over.\u000ad. You are too exhausted to continue.\u000aAn AED should be applied as soon as it arrives at the scene.\u000a\u000aPerforming Two-Rescuer Child CPR\u000aTo perform two-rescuer CPR on a child, the first aider\u000awho performs the primary survey stays at the casualty’s\u000ahead, keeping the airway open and ventilating after 15\u000acompressions. The second rescuer will compress the chest.\u000aOne cycle of two-rescuer CPR for a child is 15 compressions\u000aand 2 breaths.\u000aTo maintain effective compressions, it is recommended that\u000arescuers switch roles after every 10 cycles of compressions\u000aand ventilations (approximately 2 minutes).\u000a\u000aINFANT CPR\u000aThe small size of the infant casualty requires that CPR be\u000aadapted to their smaller form. Infants are more likely to\u000aexperience breathing emergencies than cardiac situations;\u000ahowever, prolonged respiratory arrest will lead to cardiac arrest.\u000a116'),'{"116":0.008849557522123894,"cpr":0.061946902654867256,"aed":0.02654867256637168,"this":0.008849557522123894,"one":0.017699115044247787,"cycle":0.017699115044247787,"compressions":0.04424778761061947,"ventilations":0.017699115044247787,"continue":0.017699115044247787,"until":0.008849557522123894,"applied":0.017699115044247787,"casualty":0.02654867256637168,"begins":0.008849557522123894,"respond":0.008849557522123894,"another":0.008849557522123894,"first":0.017699115044247787,"aider":0.017699115044247787,"medical":0.008849557522123894,"help":0.008849557522123894,"takes":0.008849557522123894,"over":0.008849557522123894,"you":0.008849557522123894,"are":0.017699115044247787,"too":0.008849557522123894,"exhausted":0.008849557522123894,"should":0.008849557522123894,"soon":0.008849557522123894,"arrives":0.008849557522123894,"scene":0.008849557522123894,"performing":0.008849557522123894,"two-rescuer":0.02654867256637168,"child":0.02654867256637168,"perform":0.008849557522123894,"who":0.008849557522123894,"performs":0.008849557522123894,"primary":0.008849557522123894,"survey":0.008849557522123894,"stays":0.008849557522123894,"head":0.008849557522123894,"keeping":0.008849557522123894,"airway":0.008849557522123894,"open":0.008849557522123894,"ventilating":0.008849557522123894,"after":0.017699115044247787,"second":0.008849557522123894,"rescuer":0.008849557522123894,"will":0.017699115044247787,"compress":0.008849557522123894,"chest":0.008849557522123894,"breaths":0.008849557522123894,"maintain":0.008849557522123894,"effective":0.008849557522123894,"recommended":0.008849557522123894,"rescuers":0.008849557522123894,"switch":0.008849557522123894,"roles":0.008849557522123894,"every":0.008849557522123894,"cycles":0.008849557522123894,"approximately":0.008849557522123894,"minutes":0.008849557522123894,"infant":0.017699115044247787,"small":0.008849557522123894,"size":0.008849557522123894,"requires":0.008849557522123894,"adapted":0.008849557522123894,"their":0.008849557522123894,"smaller":0.008849557522123894,"form":0.008849557522123894,"infants":0.008849557522123894,"more":0.008849557522123894,"likely":0.008849557522123894,"experience":0.008849557522123894,"breathing":0.008849557522123894,"emergencies":0.008849557522123894,"than":0.008849557522123894,"cardiac":0.017699115044247787,"situations":0.008849557522123894,"however":0.008849557522123894,"prolonged":0.008849557522123894,"respiratory":0.008849557522123894,"arrest":0.017699115044247787,"lead":0.008849557522123894}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(99,2,13,'Cardiac Arrest & CPR Protocols','Page 117',117,unistr('CPR and AED\u000a\u000aPerforming One-Rescuer Infant CPR\u000aTo perform one-rescuer infant CPR, perform the following\u000asteps:\u000a1. Perform a scene survey.\u000aa. Assess responsiveness.\u000ab. Send someone to call 9-1-1 and get an AED if\u000aavailable.\u000a\u000a05\u000a\u000a2. Perform a primary survey:\u000aa. Open the airway.\u000ab. Check for breathing for at least 5 and no more\u000athan 10 seconds.\u000ac. If the casualty is not breathing, or not breathing\u000aeffectively (agonal breaths), begin compressions\u000aimmediately.\u000a3. Give 30 compressions. Push hard. Push fast.\u000aa. Position two fingers in the centre of the chest, just\u000abelow the nipple line.\u000ab. Place your other hand behind your back, or on the\u000aground above the infant’s head.\u000ac. Press straight down on the breastbone. The depth\u000aof each compression should be 1/3 the depth of\u000athe chest.\u000ad. Release pressure and completely remove your\u000aweight at the top of each compression to allow\u000athe chest to return to the resting position.\u000a\u000a117'),'{"117":0.01020408163265306,"cpr":0.030612244897959183,"aed":0.02040816326530612,"performing":0.01020408163265306,"one-rescuer":0.02040816326530612,"infant":0.030612244897959183,"perform":0.04081632653061224,"following":0.01020408163265306,"steps":0.01020408163265306,"scene":0.01020408163265306,"survey":0.02040816326530612,"assess":0.01020408163265306,"responsiveness":0.01020408163265306,"send":0.01020408163265306,"someone":0.01020408163265306,"call":0.01020408163265306,"9-1-1":0.01020408163265306,"get":0.01020408163265306,"available":0.01020408163265306,"primary":0.01020408163265306,"open":0.01020408163265306,"airway":0.01020408163265306,"check":0.01020408163265306,"breathing":0.030612244897959183,"least":0.01020408163265306,"more":0.01020408163265306,"than":0.01020408163265306,"seconds":0.01020408163265306,"casualty":0.01020408163265306,"not":0.02040816326530612,"effectively":0.01020408163265306,"agonal":0.01020408163265306,"breaths":0.01020408163265306,"begin":0.01020408163265306,"compressions":0.02040816326530612,"immediately":0.01020408163265306,"give":0.01020408163265306,"push":0.02040816326530612,"hard":0.01020408163265306,"fast":0.01020408163265306,"position":0.02040816326530612,"two":0.01020408163265306,"fingers":0.01020408163265306,"centre":0.01020408163265306,"chest":0.030612244897959183,"just":0.01020408163265306,"below":0.01020408163265306,"nipple":0.01020408163265306,"line":0.01020408163265306,"place":0.01020408163265306,"your":0.030612244897959183,"other":0.01020408163265306,"hand":0.01020408163265306,"behind":0.01020408163265306,"back":0.01020408163265306,"ground":0.01020408163265306,"above":0.01020408163265306,"head":0.01020408163265306,"press":0.01020408163265306,"straight":0.01020408163265306,"down":0.01020408163265306,"breastbone":0.01020408163265306,"depth":0.02040816326530612,"each":0.02040816326530612,"compression":0.02040816326530612,"should":0.01020408163265306,"release":0.01020408163265306,"pressure":0.01020408163265306,"completely":0.01020408163265306,"remove":0.01020408163265306,"weight":0.01020408163265306,"top":0.01020408163265306,"allow":0.01020408163265306,"return":0.01020408163265306,"resting":0.01020408163265306}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(100,2,13,'Cardiac Arrest & CPR Protocols','Page 118',118,unistr('CPR and AED\u000a\u000a05\u000a\u000ae. Give compressions at a rate of 100 to 120 per\u000aminute. Count compressions out loud to keep\u000atrack of how many you have given, and to help\u000akeep a steady rhythm.\u000a4. Open their airway using a head-tilt/chin-lift.\u000a5. Position a barrier device and give 2 ventilations.\u000aa. For an infant casualty, seal the mouth and nose.\u000ab. The amount of air delivered is very small\u000acompared to an adult or child. This amount of air\u000ais often described as a cheek-full of air.\u000aThis is one cycle of 30:2 (30 compressions to 2 ventilations).\u000a6. Continue CPR until:\u000aa. An AED is applied.\u000ab. The casualty begins to respond.\u000ac. Another first aider or medical help takes over.\u000ad. You are too exhausted to continue.\u000aAn AED should be applied as soon as it arrives at the scene.\u000aThe back of an infant’s head is quite large compared to the\u000arest of the body, and this can cause the infant’s head to flex\u000aforward while lying on their back and cut off their airway.\u000aWhen giving CPR, it may be helpful to put a thin pad under\u000athe shoulders to help keep the airway open, but do not spend\u000atoo much time looking for a pad.\u000a\u000aPerforming Two-Rescuer Infant CPR\u000aTo perform two-rescuer CPR on an infant, the first aider\u000awho performs the primary survey stays at the casualty’s\u000ahead, keeping the airway open and ventilating after 15\u000acompressions. The second rescuer will compress the chest.\u000a118'),'{"100":0.00625,"118":0.00625,"120":0.00625,"cpr":0.03125,"aed":0.01875,"give":0.0125,"compressions":0.025,"rate":0.00625,"per":0.00625,"minute":0.00625,"count":0.00625,"out":0.00625,"loud":0.00625,"keep":0.01875,"track":0.00625,"how":0.00625,"many":0.00625,"you":0.0125,"have":0.00625,"given":0.00625,"help":0.01875,"steady":0.00625,"rhythm":0.00625,"open":0.01875,"their":0.01875,"airway":0.025,"using":0.00625,"head-tilt":0.00625,"chin-lift":0.00625,"position":0.00625,"barrier":0.00625,"device":0.00625,"ventilations":0.0125,"infant":0.03125,"casualty":0.01875,"seal":0.00625,"mouth":0.00625,"nose":0.00625,"amount":0.0125,"air":0.01875,"delivered":0.00625,"very":0.00625,"small":0.00625,"compared":0.0125,"adult":0.00625,"child":0.00625,"this":0.01875,"often":0.00625,"described":0.00625,"cheek-full":0.00625,"one":0.00625,"cycle":0.00625,"continue":0.0125,"until":0.00625,"applied":0.0125,"begins":0.00625,"respond":0.00625,"another":0.00625,"first":0.0125,"aider":0.0125,"medical":0.00625,"takes":0.00625,"over":0.00625,"are":0.00625,"too":0.0125,"exhausted":0.00625,"should":0.00625,"soon":0.00625,"arrives":0.00625,"scene":0.00625,"back":0.0125,"head":0.01875,"quite":0.00625,"large":0.00625,"rest":0.00625,"body":0.00625,"can":0.00625,"cause":0.00625,"flex":0.00625,"forward":0.00625,"while":0.00625,"lying":0.00625,"cut":0.00625,"off":0.00625,"when":0.00625,"giving":0.00625,"may":0.00625,"helpful":0.00625,"put":0.00625,"thin":0.00625,"pad":0.0125,"under":0.00625,"shoulders":0.00625,"but":0.00625,"not":0.00625,"spend":0.00625,"much":0.00625,"time":0.00625,"looking":0.00625,"performing":0.00625,"two-rescuer":0.0125,"perform":0.00625,"who":0.00625,"performs":0.00625,"primary":0.00625,"survey":0.00625,"stays":0.00625,"keeping":0.00625,"ventilating":0.00625,"after":0.00625,"second":0.00625,"rescuer":0.00625,"will":0.00625,"compress":0.00625,"chest":0.00625}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(101,2,13,'Cardiac Arrest & CPR Protocols','Page 119',119,unistr('CPR and AED\u000a\u000aOne cycle of two-rescuer CPR for\u000aan infant is 15 compressions and 2\u000abreaths.\u000aTo maintain effective compressions,\u000ait is recommended that rescuers\u000aswitch roles after every 10 cycles\u000aof compressions and ventilations\u000a(approximately 2 minutes).\u000aWhen performing two-rescuer\u000aCPR on an infant, you can use the thumb-encircling method\u000ainstead of two fingers if it is easier for positioning.\u000a\u000aAED\u000aDefibrillation is the application\u000aof an electric shock to a heart\u000athat has stopped pumping\u000aeffectively. An automated\u000aexternal defibrillator (AED) has\u000abeen proven to be one of the\u000amost important tools in saving\u000athe lives of sudden cardiac arrest\u000acasualties. It is the third link in the Chain of Survival and is the\u000aresponsibility of the first aider.\u000aAn AED is an electronic device that is programmed to\u000arecognize and shock two types of heart rhythms, Ventricular\u000aFibrillation (VF) and pulseless Ventricular Tachycardia (VT). If\u000athe machine recognizes either VT or VF in a casualty, it will\u000acharge and will indicate that a shock is advised.\u000aThe purpose of this shock is to correct the abnormal electrical\u000adisturbance and re-establish the heart rhythm.\u000a\u000a119\u000a\u000a05'),'{"119":0.009259259259259259,"cpr":0.027777777777777776,"aed":0.037037037037037035,"one":0.018518518518518517,"cycle":0.009259259259259259,"two-rescuer":0.018518518518518517,"infant":0.018518518518518517,"compressions":0.027777777777777776,"breaths":0.009259259259259259,"maintain":0.009259259259259259,"effective":0.009259259259259259,"recommended":0.009259259259259259,"rescuers":0.009259259259259259,"switch":0.009259259259259259,"roles":0.009259259259259259,"after":0.009259259259259259,"every":0.009259259259259259,"cycles":0.009259259259259259,"ventilations":0.009259259259259259,"approximately":0.009259259259259259,"minutes":0.009259259259259259,"when":0.009259259259259259,"performing":0.009259259259259259,"you":0.009259259259259259,"can":0.009259259259259259,"use":0.009259259259259259,"thumb-encircling":0.009259259259259259,"method":0.009259259259259259,"instead":0.009259259259259259,"two":0.018518518518518517,"fingers":0.009259259259259259,"easier":0.009259259259259259,"positioning":0.009259259259259259,"defibrillation":0.009259259259259259,"application":0.009259259259259259,"electric":0.009259259259259259,"shock":0.037037037037037035,"heart":0.027777777777777776,"has":0.018518518518518517,"stopped":0.009259259259259259,"pumping":0.009259259259259259,"effectively":0.009259259259259259,"automated":0.009259259259259259,"external":0.009259259259259259,"defibrillator":0.009259259259259259,"been":0.009259259259259259,"proven":0.009259259259259259,"most":0.009259259259259259,"important":0.009259259259259259,"tools":0.009259259259259259,"saving":0.009259259259259259,"lives":0.009259259259259259,"sudden":0.009259259259259259,"cardiac":0.009259259259259259,"arrest":0.009259259259259259,"casualties":0.009259259259259259,"third":0.009259259259259259,"link":0.009259259259259259,"chain":0.009259259259259259,"survival":0.009259259259259259,"responsibility":0.009259259259259259,"first":0.009259259259259259,"aider":0.009259259259259259,"electronic":0.009259259259259259,"device":0.009259259259259259,"programmed":0.009259259259259259,"recognize":0.009259259259259259,"types":0.009259259259259259,"rhythms":0.009259259259259259,"ventricular":0.018518518518518517,"fibrillation":0.009259259259259259,"pulseless":0.009259259259259259,"tachycardia":0.009259259259259259,"machine":0.009259259259259259,"recognizes":0.009259259259259259,"either":0.009259259259259259,"casualty":0.009259259259259259,"will":0.018518518518518517,"charge":0.009259259259259259,"indicate":0.009259259259259259,"advised":0.009259259259259259,"purpose":0.009259259259259259,"this":0.009259259259259259,"correct":0.009259259259259259,"abnormal":0.009259259259259259,"electrical":0.009259259259259259,"disturbance":0.009259259259259259,"re-establish":0.009259259259259259,"rhythm":0.009259259259259259}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(102,2,13,'Cardiac Arrest & CPR Protocols','Page 120',120,unistr('CPR and AED\u000a\u000aIt is important to remember that AEDs will only shock when\u000aVT or VF is present. You cannot shock a heart that is in normal\u000arhythm, nor will the machine shock when it is not appropriate,\u000asuch as when the heart is stopping (asystole) or there is\u000apulseless electrical activity (PEA).\u000a\u000a05\u000a\u000aTime is a critical factor in determining survival from cardiac\u000aarrest; the heart will only stay in fibrillation for a short time\u000abefore all electrical activity ceases. Defibrillation must\u000abe performed early to be most effective. CPR can keep\u000aoxygenated blood flowing to the brain and helps extend the\u000alength of time that the heart will remain in VT or VF, the only\u000aarrhythmias that AEDs will shock. CPR then can provide more\u000atime until the AED is attached and ready to deliver a shock.\u000a\u000aUsing an AED for an Adult\u000a\u000aTo use an AED for an adult, perform the following steps:\u000a1. Power on the AED.\u000a2. Follow the voice prompts.\u000a\u000a120'),'{"120":0.009523809523809525,"cpr":0.02857142857142857,"aed":0.047619047619047616,"important":0.009523809523809525,"remember":0.009523809523809525,"aeds":0.01904761904761905,"will":0.047619047619047616,"only":0.02857142857142857,"shock":0.047619047619047616,"when":0.02857142857142857,"present":0.009523809523809525,"you":0.009523809523809525,"cannot":0.009523809523809525,"heart":0.0380952380952381,"normal":0.009523809523809525,"rhythm":0.009523809523809525,"nor":0.009523809523809525,"machine":0.009523809523809525,"not":0.009523809523809525,"appropriate":0.009523809523809525,"such":0.009523809523809525,"stopping":0.009523809523809525,"asystole":0.009523809523809525,"there":0.009523809523809525,"pulseless":0.009523809523809525,"electrical":0.01904761904761905,"activity":0.01904761904761905,"pea":0.009523809523809525,"time":0.0380952380952381,"critical":0.009523809523809525,"factor":0.009523809523809525,"determining":0.009523809523809525,"survival":0.009523809523809525,"from":0.009523809523809525,"cardiac":0.009523809523809525,"arrest":0.009523809523809525,"stay":0.009523809523809525,"fibrillation":0.009523809523809525,"short":0.009523809523809525,"before":0.009523809523809525,"all":0.009523809523809525,"ceases":0.009523809523809525,"defibrillation":0.009523809523809525,"must":0.009523809523809525,"performed":0.009523809523809525,"early":0.009523809523809525,"most":0.009523809523809525,"effective":0.009523809523809525,"can":0.01904761904761905,"keep":0.009523809523809525,"oxygenated":0.009523809523809525,"blood":0.009523809523809525,"flowing":0.009523809523809525,"brain":0.009523809523809525,"helps":0.009523809523809525,"extend":0.009523809523809525,"length":0.009523809523809525,"remain":0.009523809523809525,"arrhythmias":0.009523809523809525,"then":0.009523809523809525,"provide":0.009523809523809525,"more":0.009523809523809525,"until":0.009523809523809525,"attached":0.009523809523809525,"ready":0.009523809523809525,"deliver":0.009523809523809525,"using":0.009523809523809525,"adult":0.01904761904761905,"use":0.009523809523809525,"perform":0.009523809523809525,"following":0.009523809523809525,"steps":0.009523809523809525,"power":0.009523809523809525,"follow":0.009523809523809525,"voice":0.009523809523809525,"prompts":0.009523809523809525}','ACTIVE','2026-09-13 11:57:00','2026-09-13 11:57:00');
INSERT INTO knowledge_chunks VALUES(103,2,13,'Cardiac Arrest & CPR Protocols','Page 121',121,unistr('CPR and AED\u000a\u000aThe audio instructions will direct you to:\u000a Bare the chest and attach electrode pads. The pads need\u000ato stick directly to the skin, so excessive sweat, water, and\u000achest hair need to be removed before application.\u000a\u000a05\u000a\u000a Stand back (or clear).\u000a Press the shock button and/or continue CPR as prompted\u000aby the machine.\u000aContinue with CPR and listen for the AED to give additional\u000ainstructions.\u000a\u000aUsing an AED for a Child or Infant\u000aAn AED can be used on a child or an infant. An AED with child\u000apads should be used according to the directions on the pads.\u000aMost AEDs are stocked with pads designed for adult\u000acasualties. If an AED does not have specific pads for a child,\u000aadult pads can be used by placing them on the front and\u000aback of the child or infant.\u000aDefibrillation Special Considerations and Circumstances\u000a\u000a121'),'{"121":0.010752688172043012,"cpr":0.03225806451612903,"aed":0.06451612903225806,"audio":0.010752688172043012,"instructions":0.021505376344086023,"will":0.010752688172043012,"direct":0.010752688172043012,"you":0.010752688172043012,"bare":0.010752688172043012,"chest":0.021505376344086023,"attach":0.010752688172043012,"electrode":0.010752688172043012,"pads":0.07526881720430108,"need":0.021505376344086023,"stick":0.010752688172043012,"directly":0.010752688172043012,"skin":0.010752688172043012,"excessive":0.010752688172043012,"sweat":0.010752688172043012,"water":0.010752688172043012,"hair":0.010752688172043012,"removed":0.010752688172043012,"before":0.010752688172043012,"application":0.010752688172043012,"stand":0.010752688172043012,"back":0.021505376344086023,"clear":0.010752688172043012,"press":0.010752688172043012,"shock":0.010752688172043012,"button":0.010752688172043012,"continue":0.021505376344086023,"prompted":0.010752688172043012,"machine":0.010752688172043012,"with":0.03225806451612903,"listen":0.010752688172043012,"give":0.010752688172043012,"additional":0.010752688172043012,"using":0.010752688172043012,"child":0.053763440860215055,"infant":0.03225806451612903,"can":0.021505376344086023,"used":0.03225806451612903,"should":0.010752688172043012,"according":0.010752688172043012,"directions":0.010752688172043012,"most":0.010752688172043012,"aeds":0.010752688172043012,"are":0.010752688172043012,"stocked":0.010752688172043012,"designed":0.010752688172043012,"adult":0.021505376344086023,"casualties":0.010752688172043012,"does":0.010752688172043012,"not":0.010752688172043012,"have":0.010752688172043012,"specific":0.010752688172043012,"placing":0.010752688172043012,"them":0.010752688172043012,"front":0.010752688172043012,"defibrillation":0.010752688172043012,"special":0.010752688172043012,"considerations":0.010752688172043012,"circumstances":0.010752688172043012}','ACTIVE','2026-09-13 11:57:01','2026-09-13 11:57:01');
INSERT INTO knowledge_chunks VALUES(104,2,13,'Cardiac Arrest & CPR Protocols','Page 122',122,unistr('CPR and AED\u000a\u000a05\u000aThe following are special considerations and circumstances\u000aregarding defibrillation:\u000aPregnant women AEDs can be safely used in all stages of\u000apregnancy.\u000aPacemakers or implanted defibrillators Defibrillator pads\u000ashould not be placed directly over a pacemaker site but\u000ashould be approximately 2.5 cm (one inch) away.\u000aLook for scars or lumps on the chest as an indicator of\u000aimplanted devices.\u000aPatch medications Some casualties wear a patch that contains\u000amedication such as nitroglycerin for angina. If the patch is\u000ain the way of the pad placement, gently remove it from the\u000achest with gloved hands and wipe the area clean.\u000aWet environment AEDs can be used in wet areas. Dry the\u000achest to ensure good pad contact. Move the casualty to a dry\u000aarea if possible. If you or the casualty is submerged in water,\u000aavoid using the AED. Generally, if the water does not splash\u000awhen you tap your foot, it is safe.\u000aMetal surfaces AEDs can be used safely with the casualty on a\u000ametal surface. A blanket can be placed between the casualty\u000aand the metal surface if you are concerned.\u000a122'),'{"122":0.008,"cpr":0.008,"aed":0.016,"following":0.008,"are":0.016,"special":0.008,"considerations":0.008,"circumstances":0.008,"regarding":0.008,"defibrillation":0.008,"pregnant":0.008,"women":0.008,"aeds":0.024,"can":0.032,"safely":0.016,"used":0.024,"all":0.008,"stages":0.008,"pregnancy":0.008,"pacemakers":0.008,"implanted":0.016,"defibrillators":0.008,"defibrillator":0.008,"pads":0.008,"should":0.016,"not":0.016,"placed":0.016,"directly":0.008,"over":0.008,"pacemaker":0.008,"site":0.008,"but":0.008,"approximately":0.008,"one":0.008,"inch":0.008,"away":0.008,"look":0.008,"scars":0.008,"lumps":0.008,"chest":0.024,"indicator":0.008,"devices":0.008,"patch":0.024,"medications":0.008,"some":0.008,"casualties":0.008,"wear":0.008,"contains":0.008,"medication":0.008,"such":0.008,"nitroglycerin":0.008,"angina":0.008,"way":0.008,"pad":0.016,"placement":0.008,"gently":0.008,"remove":0.008,"from":0.008,"with":0.016,"gloved":0.008,"hands":0.008,"wipe":0.008,"area":0.016,"clean":0.008,"wet":0.016,"environment":0.008,"areas":0.008,"dry":0.016,"ensure":0.008,"good":0.008,"contact":0.008,"move":0.008,"casualty":0.032,"possible":0.008,"you":0.024,"submerged":0.008,"water":0.016,"avoid":0.008,"using":0.008,"generally":0.008,"does":0.008,"splash":0.008,"when":0.008,"tap":0.008,"your":0.008,"foot":0.008,"safe":0.008,"metal":0.024,"surfaces":0.008,"surface":0.016,"blanket":0.008,"between":0.008,"concerned":0.008}','ACTIVE','2026-09-13 11:57:01','2026-09-13 11:57:01');
INSERT INTO knowledge_chunks VALUES(105,2,13,'Cardiac Arrest & CPR Protocols','Page 123',123,unistr('CPR and AED\u000a\u000aJewelry and piercings Avoid placing pads over top of\u000apiercings, jewelry, or anything that would cause a gap. AED\u000apads should adhere flat to the skin.\u000aEnvironment Ensure the environment you are using an AED in\u000adoes not contain explosive gases.\u000a\u000aPost-Resuscitation Care and Handover to\u000aEMS\u000aIf defibrillation is successful, the casualty may start breathing\u000aon their own but remain unresponsive. In this case, place the\u000acasualty into the recovery position and monitor the ABCs.\u000aLeave the AED attached. The AED will continually monitor\u000athe heart rhythm, or you may need to use the device again.\u000aCertain information is important for emergency services\u000apersonnel, such as the time of collapse, time when CPR was\u000astarted, time when first shock was delivered, and number\u000aof shocks. Provide as much detail as possible and follow\u000athe directions of medical personnel once they arrive on the\u000ascene.\u000a\u000aAED Workplace Policies and Procedures\u000aRegulations concerning the requirement of a workplace\u000ato have an AED, and the necessary policies about AEDs,\u000awill be contained within federal, provincial, or territorial\u000alegislation. Where not specifically outlined by regulations,\u000aa workplace’should have an established AED policy which\u000aoutlines:\u000a Certification and recertification requirements\u000a Maintenance and inspection processes\u000a Post-use process (downloading information, resupplying\u000apads and rescue pouch, etc.)\u000a Replacement of batteries and pads\u000a Replacement of unit at its end-of-life\u000a123\u000a\u000a05'),'{"123":0.006134969325153374,"cpr":0.012269938650306749,"aed":0.049079754601226995,"jewelry":0.012269938650306749,"piercings":0.012269938650306749,"avoid":0.006134969325153374,"placing":0.006134969325153374,"pads":0.024539877300613498,"over":0.006134969325153374,"top":0.006134969325153374,"anything":0.006134969325153374,"would":0.006134969325153374,"cause":0.006134969325153374,"gap":0.006134969325153374,"should":0.012269938650306749,"adhere":0.006134969325153374,"flat":0.006134969325153374,"skin":0.006134969325153374,"environment":0.012269938650306749,"ensure":0.006134969325153374,"you":0.012269938650306749,"are":0.006134969325153374,"using":0.006134969325153374,"does":0.006134969325153374,"not":0.012269938650306749,"contain":0.006134969325153374,"explosive":0.006134969325153374,"gases":0.006134969325153374,"post-resuscitation":0.006134969325153374,"care":0.006134969325153374,"handover":0.006134969325153374,"ems":0.006134969325153374,"defibrillation":0.006134969325153374,"successful":0.006134969325153374,"casualty":0.012269938650306749,"may":0.012269938650306749,"start":0.006134969325153374,"breathing":0.006134969325153374,"their":0.006134969325153374,"own":0.006134969325153374,"but":0.006134969325153374,"remain":0.006134969325153374,"unresponsive":0.006134969325153374,"this":0.006134969325153374,"case":0.006134969325153374,"place":0.006134969325153374,"into":0.006134969325153374,"recovery":0.006134969325153374,"position":0.006134969325153374,"monitor":0.012269938650306749,"abcs":0.006134969325153374,"leave":0.006134969325153374,"attached":0.006134969325153374,"will":0.012269938650306749,"continually":0.006134969325153374,"heart":0.006134969325153374,"rhythm":0.006134969325153374,"need":0.006134969325153374,"use":0.006134969325153374,"device":0.006134969325153374,"again":0.006134969325153374,"certain":0.006134969325153374,"information":0.012269938650306749,"important":0.006134969325153374,"emergency":0.006134969325153374,"services":0.006134969325153374,"personnel":0.012269938650306749,"such":0.006134969325153374,"time":0.018404907975460124,"collapse":0.006134969325153374,"when":0.012269938650306749,"was":0.012269938650306749,"started":0.006134969325153374,"first":0.00613496932515